"Matemática|Porcentagem":{concept:"Porcentagem significa uma quantidade em cada 100 partes. Para calcular 20% de 150, multiplique 150 por 20 e divida por 100.",example:"20% de 150 = 150 × 20 ÷ 100 = 30.",question:"Quanto é 25% de 200?",options:["25","50","75"],correct:1,detail:"200 × 25 ÷ 100 = 50."},
"Matemática|Álgebra":{concept:"Uma variável representa um número desconhecido. Para resolver uma equação, mantenha a igualdade ao realizar a mesma operação nos dois lados.",example:"x + 7 = 12. Subtraindo 7 dos dois lados: x = 5.",question:"Se x + 9 = 15, qual é x?",options:["6","9","24"],correct:0,detail:"15 − 9 = 6."},
