const expandedPortuguese:Record<string,[string,string,string,string,[string,string,string],number,string][]> = {"Português|Redação":[["Tema e recorte","Antes de escrever, identifique o assunto e delimite o problema específico que será discutido.","Tema: tecnologia. Recorte: uso excessivo de telas por adolescentes.","Qual é um recorte específico do tema educação?",["Educação","Evasão escolar no ensino médio","Sociedade"],1,"O recorte delimita uma questão concreta dentro do tema."],["Tese e posicionamento","A tese é a ideia central defendida ao longo do texto. Deve responder ao problema proposto.","A escola deve promover educação digital para reduzir riscos do uso de redes sociais.","Qual frase apresenta uma tese?",["A internet existe","Há diferentes aplicativos","A educação digital deve integrar o currículo"],2,"A terceira frase defende um posicionamento."],["Introdução","Uma introdução eficiente contextualiza o tema, apresenta o problema e indica a tese.","Contexto: crescimento das redes. Problema: desinformação. Tese: educação midiática é necessária.","O que não pode faltar na introdução argumentativa?",["A tese","Uma lista de referências","Uma conclusão repetida"],0,"A tese orienta a argumentação do texto."],["Argumentos e evidências","Cada argumento precisa explicar por que a tese é defensável e pode ser sustentado por dados, exemplos ou relações de causa e efeito.","Argumento: a educação midiática ajuda a verificar fontes antes de compartilhar notícias.","O que fortalece um argumento?",["Repetir a tese","Evidência pertinente e explicação","Mudar de assunto"],1,"Evidências devem estar ligadas à justificativa apresentada."],["Desenvolvimento e coesão","Organize cada parágrafo em ideia central, explicação e consequência. Conectivos tornam as relações explícitas.","Além disso, a leitura crítica reduz a circulação de informações enganosas.","Qual conectivo indica adição?",["Entretanto","Portanto","Além disso"],2,"Além disso acrescenta um argumento à discussão."],["Conclusão e revisão","Retome a tese sem copiá-la literalmente, sintetize o raciocínio e apresente encaminhamento quando a proposta exigir. Revise clareza e gramática.","Conclui-se que formar leitores críticos exige ações coordenadas entre escola e comunidade.","Qual é a função da conclusão?",["Introduzir tema novo","Encerrar o raciocínio com coerência","Repetir todo o desenvolvimento"],1,"A conclusão fecha a linha argumentativa."]],"Português|Interpretação":[["Informação explícita","Informação explícita aparece diretamente no texto e pode ser localizada por palavras ou paráfrases.","Texto: 'Luísa saiu às sete'. A hora informada é sete.","O que é uma informação explícita?",["Algo escrito no texto","Uma hipótese sem evidência","A opinião do leitor"],0,"A informação pode ser encontrada diretamente no enunciado."],["Inferência","Inferir é concluir algo não dito literalmente com base em pistas textuais.","'João pegou o casaco ao ver a neve'. É razoável inferir que fazia frio.","Qual inferência é sustentada pelo exemplo?",["João viajou ontem","Provavelmente fazia frio","João comprou um casaco"],1,"A neve e o casaco sustentam a inferência sobre o frio."],["Tema e ideia central","O tema indica sobre o que o texto trata; a ideia central expressa o que ele comunica a respeito desse tema.","Tema: água. Ideia central: economizar água reduz desperdício.","Qual alternativa expressa uma ideia central?",["Água","Economizar água evita desperdício","Economia"],1,"A ideia central apresenta uma afirmação sobre o tema."],["Fato e opinião","Fatos podem ser verificados; opiniões expressam avaliações, preferências ou julgamentos.","Fato: a biblioteca abre às oito. Opinião: é a melhor biblioteca da cidade.","Qual frase é opinião?",["A aula começa às nove","O livro tem 120 páginas","Este é o melhor livro"],2,"'Melhor' é um julgamento subjetivo."],["Intenção comunicativa","Identifique se o texto busca informar, convencer, orientar, narrar ou entreter.","Um manual com etapas de instalação tem intenção de orientar.","Qual é a finalidade principal de uma receita?",["Orientar o preparo","Defender uma tese","Relatar uma viagem"],0,"A receita organiza instruções para executar uma tarefa."],["Sentido no contexto","Uma palavra pode ter sentidos diferentes conforme a frase. Leia o entorno antes de escolher o significado.","'A notícia caiu como uma bomba' emprega bomba em sentido figurado.","No exemplo, 'bomba' indica:",["Explosivo real","Grande impacto","Objeto escolar"],1,"A expressão indica forte repercussão, não explosão literal."]],"Português|Gramática":[["Classes de palavras","Substantivos nomeiam seres e ideias; adjetivos caracterizam; verbos indicam ações, estados ou fenômenos.","Na frase 'A menina curiosa lê', menina é substantivo, curiosa é adjetivo e lê é verbo.","Qual palavra é adjetivo em 'O aluno dedicado estudou'?",["Aluno","Dedicado","Estudou"],1,"Dedicado caracteriza o substantivo aluno."],["Sujeito e predicado","O sujeito é o termo sobre o qual se declara algo; o predicado contém a informação declarada.","'Os estudantes chegaram cedo': sujeito = os estudantes; predicado = chegaram cedo.","Qual é o sujeito em 'As crianças brincam'?",["Brincam","As crianças","Crianças brincam"],1,"O termo 'As crianças' é o sujeito da oração."],["Concordância verbal","O verbo concorda com o núcleo do sujeito em número e pessoa.","'As professoras explicam' está no plural porque o sujeito é plural.","Qual frase está correta?",["Os alunos estuda","Os alunos estudam","Os aluno estudam"],1,"Sujeito plural pede verbo no plural."],["Pontuação","Vírgulas organizam elementos, isolam vocativos e marcam certas estruturas, mas não devem separar sujeito e verbo sem motivo.","'Maria, venha aqui.' A vírgula isola o vocativo Maria.","Qual frase usa corretamente o vocativo?",["Pedro venha aqui","Pedro, venha aqui","Pedro venha, aqui"],1,"O vocativo Pedro deve ser separado por vírgula."],["Crase","A crase pode ocorrer na fusão da preposição a com o artigo feminino a. Verifique a regência e a presença do artigo.","'Vou à escola': quem vai, vai a algum lugar; escola admite artigo a.","Qual frase está correta?",["Vou à escola","Vou à pé","Cheguei à ontem"],0,"Em 'à escola' ocorre a fusão de preposição e artigo."],["Coesão e pronomes","Pronomes podem retomar termos anteriores e evitar repetições, desde que a referência permaneça clara.","'Ana comprou um livro. Ela começou a lê-lo.' Ela retoma Ana.","A que se refere 'Ela' no exemplo?",["Livro","Ana","Nenhum termo"],1,"Ela retoma o substantivo próprio Ana."]],"Português|Literatura":[["Texto literário","A literatura explora linguagem, imagens, ritmo e sentidos; o texto literário pode admitir diferentes interpretações fundamentadas.","Uma metáfora como 'o tempo é um rio' cria uma comparação implícita.","Qual recurso aparece em 'o tempo é um rio'?",["Metáfora","Manual de instruções","Equação"],0,"A expressão associa tempo e rio sem usar 'como'."],["Narrador e foco narrativo","Narrador em primeira pessoa participa ou testemunha a história; em terceira pessoa narra de fora dos acontecimentos.","'Eu abri a porta' indica narração em primeira pessoa.","Qual frase usa primeira pessoa?",["Ele saiu","Eu saí","Eles saíram"],1,"O pronome eu marca a primeira pessoa."],["Personagem, tempo e espaço","A narrativa apresenta agentes, acontecimentos, ambiente e organização temporal.","'Naquela manhã, Clara entrou na estação' informa personagem, tempo e espaço.","Qual é o espaço no exemplo?",["Clara","Manhã","Estação"],2,"A estação é o lugar onde a cena ocorre."],["Gêneros literários","Narrativas contam acontecimentos; poemas exploram versos e ritmo; textos dramáticos são organizados para encenação.","Um texto com falas de personagens e rubricas pode ser dramático.","Qual gênero é escrito para encenação?",["Dramático","Manual técnico","Notícia"],0,"O gênero dramático é estruturado para representação."],["Figuras de linguagem","Metáfora, comparação, personificação e hipérbole produzem efeitos expressivos distintos.","'O vento sussurrava' atribui ação humana ao vento.","Qual figura aparece no exemplo?",["Personificação","Enumeração","Pleonasmo"],0,"O vento recebe a ação humana de sussurrar."],["Leitura crítica","Analise como escolhas do narrador, contexto histórico e recursos de linguagem constroem sentidos.","Uma narrativa pode apresentar fatos pela perspectiva limitada de um personagem.","Por que considerar o narrador?",["Porque toda narração é neutra","Porque a perspectiva influencia o relato","Porque elimina o contexto"],1,"A perspectiva determina quais informações chegam ao leitor."]]};
const expandedChemistryAdvanced:Record<string,[string,string,string,string,[string,string,string],number,string][]> = {"Química|Átomos":[["Modelos atômicos","Modelos atômicos mudaram com novas evidências experimentais.","Dalton descreveu átomos como esferas indivisíveis; Thomson propôs elétrons.","Qual modelo introduziu elétrons na estrutura atômica?",["Dalton","Thomson","Demócrito"],1,"Resposta correta: Thomson. Modelos atômicos mudaram com novas evidências experimentais. Exemplo: Dalton descreveu átomos como esferas indivisíveis; Thomson propôs elétrons."],["Experimento de Rutherford","O espalhamento de partículas alfa revelou um núcleo pequeno e positivo.","A maioria das partículas atravessou a lâmina de ouro; poucas sofreram grandes desvios.","O experimento indicou que o átomo possui:",["Núcleo concentrado","Massa uniforme","Ausência de espaços"],0,"Resposta correta: Núcleo concentrado. O espalhamento de partículas alfa revelou um núcleo pequeno e positivo. Exemplo: A maioria das partículas atravessou a lâmina de ouro; poucas sofreram grandes desvios."],["Prótons, nêutrons e elétrons","Prótons são positivos, nêutrons neutros e elétrons negativos.","O núcleo contém prótons e nêutrons; elétrons ocupam regiões ao redor.","Qual partícula tem carga negativa?",["Próton","Nêutron","Elétron"],2,"Resposta correta: Elétron. Prótons são positivos, nêutrons neutros e elétrons negativos. Exemplo: O núcleo contém prótons e nêutrons; elétrons ocupam regiões ao redor."],["Número atômico","O número atômico Z é a quantidade de prótons no núcleo.","O carbono possui Z=6 e portanto seis prótons.","Um átomo com Z=8 possui:",["8 prótons","8 nêutrons obrigatoriamente","16 elétrons obrigatoriamente"],0,"Resposta correta: 8 prótons. O número atômico Z é a quantidade de prótons no núcleo. Exemplo: O carbono possui Z=6 e portanto seis prótons."],["Número de massa","Número de massa A é a soma de prótons e nêutrons.","Um núcleo com 6 prótons e 7 nêutrons tem A=13.","Com 11 prótons e 12 nêutrons, A vale:",["11","12","23"],2,"Resposta correta: 23. Número de massa A é a soma de prótons e nêutrons. Exemplo: Um núcleo com 6 prótons e 7 nêutrons tem A=13."],["Isótopos","Isótopos têm mesmo número de prótons e diferentes números de nêutrons.","Carbono-12 e carbono-14 têm Z=6 e massas distintas.","Isótopos do mesmo elemento diferem em:",["Número de prótons","Número de nêutrons","Carga do próton"],1,"Resposta correta: Número de nêutrons. Isótopos têm mesmo número de prótons e diferentes números de nêutrons. Exemplo: Carbono-12 e carbono-14 têm Z=6 e massas distintas."],["Íons","Íons são espécies com carga líquida por perda ou ganho de elétrons.","Na⁺ resulta da perda de um elétron por um átomo neutro de sódio.","Um cátion é formado quando o átomo:",["Perde elétrons","Ganha nêutrons","Ganha elétrons"],0,"Resposta correta: Perde elétrons. Íons são espécies com carga líquida por perda ou ganho de elétrons. Exemplo: Na⁺ resulta da perda de um elétron por um átomo neutro de sódio."],["Cátions e ânions","Cátions têm carga positiva; ânions têm carga negativa.","Cl⁻ é ânion; Mg²⁺ é cátion.","Qual espécie é ânion?",["K⁺","Cl⁻","Ca²⁺"],1,"Resposta correta: Cl⁻. Cátions têm carga positiva; ânions têm carga negativa. Exemplo: Cl⁻ é ânion; Mg²⁺ é cátion."],["Eletrosfera e níveis","Elétrons ocupam níveis e subníveis de energia quantizados.","A transição entre níveis pode envolver emissão ou absorção de fótons.","Quando um elétron passa a nível mais alto, ele:",["Absorve energia","Desaparece","Vira próton"],0,"Resposta correta: Absorve energia. Elétrons ocupam níveis e subníveis de energia quantizados. Exemplo: A transição entre níveis pode envolver emissão ou absorção de fótons."],["Configuração eletrônica","A distribuição eletrônica descreve ocupação de orbitais segundo regras quânticas.","O hidrogênio no estado fundamental tem configuração 1s¹.","Qual configuração corresponde ao hélio neutro no estado fundamental?",["1s¹","1s²","2s²"],1,"Resposta correta: 1s². A distribuição eletrônica descreve ocupação de orbitais segundo regras quânticas. Exemplo: O hidrogênio no estado fundamental tem configuração 1s¹."],["Elétrons de valência","Elétrons de valência participam frequentemente das ligações químicas.","O sódio possui um elétron na camada de valência em seu estado fundamental.","Elétrons de valência estão associados principalmente a:",["Ligações químicas","Massa dos nêutrons","Número de prótons"],0,"Resposta correta: Ligações químicas. Elétrons de valência participam frequentemente das ligações químicas. Exemplo: O sódio possui um elétron na camada de valência em seu estado fundamental."],["Orbitais","Orbitais descrevem regiões de probabilidade de encontrar elétrons.","O subnível p comporta até seis elétrons.","Quantos elétrons cabem no subnível s?",["2","6","10"],0,"Resposta correta: 2. Orbitais descrevem regiões de probabilidade de encontrar elétrons. Exemplo: O subnível p comporta até seis elétrons."],["Princípio de Pauli","Em um átomo, dois elétrons não podem ter os quatro números quânticos iguais.","Um orbital comporta no máximo dois elétrons com spins opostos.","Um orbital pode comportar no máximo:",["1 elétron","2 elétrons","8 elétrons"],1,"Resposta correta: 2 elétrons. Em um átomo, dois elétrons não podem ter os quatro números quânticos iguais. Exemplo: Um orbital comporta no máximo dois elétrons com spins opostos."],["Transições eletrônicas","Elétrons podem absorver ou emitir energia em transições entre estados.","Emissão ocorre quando um elétron passa para estado de menor energia.","Uma transição para menor energia pode emitir:",["Fóton","Próton","Nêutron"],0,"Resposta correta: Fóton. Elétrons podem absorver ou emitir energia em transições entre estados. Exemplo: Emissão ocorre quando um elétron passa para estado de menor energia."],["Massa atômica média","Massa atômica na tabela é média ponderada das massas isotópicas naturais.","Isótopos mais abundantes contribuem mais para a média.","A massa atômica média depende:",["Das abundâncias isotópicas","Apenas do isótopo mais pesado","Da cor do elemento"],0,"Resposta correta: Das abundâncias isotópicas. Massa atômica na tabela é média ponderada das massas isotópicas naturais. Exemplo: Isótopos mais abundantes contribuem mais para a média."],["Radioatividade","Núcleos instáveis podem emitir radiação durante transformações nucleares.","Na emissão alfa, o núcleo perde dois prótons e dois nêutrons.","Na emissão alfa, o número atômico diminui em:",["1","2","4"],1,"Resposta correta: 2. Núcleos instáveis podem emitir radiação durante transformações nucleares. Exemplo: Na emissão alfa, o núcleo perde dois prótons e dois nêutrons."]],"Química|Tabela periódica":[["Organização por número atômico","A tabela moderna ordena elementos por número atômico crescente.","H tem Z=1; He tem Z=2.","A tabela moderna é ordenada por:",["Massa total","Número atômico","Densidade"],1,"Resposta correta: Número atômico. A tabela moderna ordena elementos por número atômico crescente. Exemplo: H tem Z=1; He tem Z=2."],["Períodos","Períodos são linhas horizontais da tabela periódica.","Sódio e magnésio estão no terceiro período.","Um período corresponde a uma:",["Linha horizontal","Coluna vertical","Ligação covalente"],0,"Resposta correta: Linha horizontal. Períodos são linhas horizontais da tabela periódica. Exemplo: Sódio e magnésio estão no terceiro período."],["Grupos","Grupos são colunas cujos elementos frequentemente têm propriedades semelhantes.","Lítio e sódio pertencem ao grupo 1.","Um grupo é uma:",["Linha horizontal","Coluna vertical","Camada nuclear"],1,"Resposta correta: Coluna vertical. Grupos são colunas cujos elementos frequentemente têm propriedades semelhantes. Exemplo: Lítio e sódio pertencem ao grupo 1."],["Metais alcalinos","Metais alcalinos do grupo 1 são reativos e formam frequentemente íons +1.","Sódio e potássio são metais alcalinos.","Qual elemento é metal alcalino?",["Neônio","Potássio","Cloro"],1,"Resposta correta: Potássio. Metais alcalinos do grupo 1 são reativos e formam frequentemente íons +1. Exemplo: Sódio e potássio são metais alcalinos."],["Metais alcalino-terrosos","Elementos do grupo 2 formam frequentemente cátions +2.","Magnésio e cálcio pertencem ao grupo 2.","Qual pertence ao grupo 2?",["Cálcio","Sódio","Argônio"],0,"Resposta correta: Cálcio. Elementos do grupo 2 formam frequentemente cátions +2. Exemplo: Magnésio e cálcio pertencem ao grupo 2."],["Halogênios","Halogênios do grupo 17 são não metais reativos.","Flúor e cloro são halogênios.","Qual elemento é halogênio?",["Cloro","Hélio","Ferro"],0,"Resposta correta: Cloro. Halogênios do grupo 17 são não metais reativos. Exemplo: Flúor e cloro são halogênios."],["Gases nobres","Gases nobres possuem camadas de valência completas em seus estados fundamentais, com baixa reatividade usual.","Neônio é usado em lâmpadas de descarga.","Qual é gás nobre?",["Oxigênio","Argônio","Sódio"],1,"Resposta correta: Argônio. Gases nobres possuem camadas de valência completas em seus estados fundamentais, com baixa reatividade usual. Exemplo: Neônio é usado em lâmpadas de descarga."],["Metais de transição","Muitos metais de transição apresentam diferentes estados de oxidação.","Ferro pode formar Fe²⁺ e Fe³⁺.","Qual é metal de transição?",["Ferro","Hidrogênio","Neônio"],0,"Resposta correta: Ferro. Muitos metais de transição apresentam diferentes estados de oxidação. Exemplo: Ferro pode formar Fe²⁺ e Fe³⁺."],["Metais e não metais","Metais geralmente conduzem eletricidade; não metais apresentam propriedades diversas.","Cobre é metal condutor; enxofre é não metal.","Qual é não metal?",["Alumínio","Enxofre","Cobre"],1,"Resposta correta: Enxofre. Metais geralmente conduzem eletricidade; não metais apresentam propriedades diversas. Exemplo: Cobre é metal condutor; enxofre é não metal."],["Semimetais","Semimetais apresentam propriedades intermediárias e são importantes em semicondutores.","Silício é amplamente utilizado em dispositivos eletrônicos.","Qual é semimetal?",["Silício","Sódio","Bromo"],0,"Resposta correta: Silício. Semimetais apresentam propriedades intermediárias e são importantes em semicondutores. Exemplo: Silício é amplamente utilizado em dispositivos eletrônicos."],["Raio atômico","Em um mesmo período, o raio atômico tende a diminuir da esquerda para a direita.","O aumento da carga nuclear efetiva atrai mais fortemente os elétrons.","Ao longo de um período, o raio tende a:",["Diminuir","Aumentar sempre","Permanecer idêntico"],0,"Resposta correta: Diminuir. Em um mesmo período, o raio atômico tende a diminuir da esquerda para a direita. Exemplo: O aumento da carga nuclear efetiva atrai mais fortemente os elétrons."],["Energia de ionização","Energia de ionização é necessária para remover elétron de espécie gasosa.","Gases nobres apresentam geralmente altas energias de primeira ionização.","A primeira ionização remove:",["Um elétron","Um próton","Um nêutron"],0,"Resposta correta: Um elétron. Energia de ionização é necessária para remover elétron de espécie gasosa. Exemplo: Gases nobres apresentam geralmente altas energias de primeira ionização."],["Eletronegatividade","Eletronegatividade expressa a tendência de atrair elétrons compartilhados numa ligação.","Flúor é muito eletronegativo.","Qual elemento é o mais eletronegativo na escala de Pauling?",["Sódio","Flúor","Césio"],1,"Resposta correta: Flúor. Eletronegatividade expressa a tendência de atrair elétrons compartilhados numa ligação. Exemplo: Flúor é muito eletronegativo."],["Afinidade eletrônica","Afinidade eletrônica está relacionada à variação de energia ao adicionar elétron a espécie gasosa.","Halogênios geralmente liberam energia ao receber um elétron.","Afinidade eletrônica envolve:",["Adição de elétron","Remoção de próton","Fusão nuclear"],0,"Resposta correta: Adição de elétron. Afinidade eletrônica está relacionada à variação de energia ao adicionar elétron a espécie gasosa. Exemplo: Halogênios geralmente liberam energia ao receber um elétron."],["Estados de oxidação","Número de oxidação auxilia a acompanhar transferências formais de elétrons.","No NaCl, sódio tem NOX +1 e cloro −1.","Qual o NOX do sódio em NaCl?",["+1","−1","0"],0,"Resposta correta: +1. Número de oxidação auxilia a acompanhar transferências formais de elétrons. Exemplo: No NaCl, sódio tem NOX +1 e cloro −1."],["Previsão de propriedades","A posição na tabela ajuda a prever valência e comportamento químico.","Elementos do mesmo grupo costumam apresentar tendências semelhantes.","Elementos do mesmo grupo tendem a compartilhar:",["Propriedades químicas","Mesmo número de massa","Mesmo número de nêutrons"],0,"Resposta correta: Propriedades químicas. A posição na tabela ajuda a prever valência e comportamento químico. Exemplo: Elementos do mesmo grupo costumam apresentar tendências semelhantes."]],"Química|Reações":[["Reagentes e produtos","Reagentes são consumidos e produtos são formados numa reação química.","Hidrogênio e oxigênio podem reagir para formar água.","Em uma equação química, produtos ficam geralmente:",["À direita da seta","À esquerda da seta","Sob o símbolo de carga"],0,"Resposta correta: À direita da seta. Reagentes são consumidos e produtos são formados numa reação química. Exemplo: Hidrogênio e oxigênio podem reagir para formar água."],["Evidências de reação","Mudanças de cor, formação de gás ou precipitado podem indicar transformação química.","Vinagre e bicarbonato produzem gás carbônico.","Formação de bolhas numa mistura pode indicar:",["Produção de gás","Apenas fusão","Apenas evaporação"],0,"Resposta correta: Produção de gás. Mudanças de cor, formação de gás ou precipitado podem indicar transformação química. Exemplo: Vinagre e bicarbonato produzem gás carbônico."],["Conservação da massa","Em sistema fechado, a massa total se conserva durante reações químicas comuns.","10 g de reagentes originam 10 g de produtos num sistema fechado.","Se reagentes somam 25 g, produtos somam:",["20 g","25 g","30 g"],1,"Resposta correta: 25 g. Em sistema fechado, a massa total se conserva durante reações químicas comuns. Exemplo: 10 g de reagentes originam 10 g de produtos num sistema fechado."],["Balanceamento de equações","Coeficientes ajustam a quantidade de átomos de cada elemento em ambos os lados.","2H₂ + O₂ → 2H₂O conserva H e O.","Em 2H₂ + O₂ → 2H₂O, coeficiente de H₂O é:",["1","2","4"],1,"Resposta correta: 2. Coeficientes ajustam a quantidade de átomos de cada elemento em ambos os lados. Exemplo: 2H₂ + O₂ → 2H₂O conserva H e O."],["Síntese química","Reação de síntese forma produto a partir de reagentes mais simples.","2Mg + O₂ → 2MgO é síntese.","A + B → AB representa:",["Decomposição","Síntese","Neutralização obrigatória"],1,"Resposta correta: Síntese. Reação de síntese forma produto a partir de reagentes mais simples. Exemplo: 2Mg + O₂ → 2MgO é síntese."],["Decomposição","Decomposição transforma uma substância em espécies mais simples.","2H₂O₂ → 2H₂O + O₂.","AB → A + B representa:",["Síntese","Decomposição","Precipitação obrigatória"],1,"Resposta correta: Decomposição. Decomposição transforma uma substância em espécies mais simples. Exemplo: 2H₂O₂ → 2H₂O + O₂."],["Combustão","Combustão envolve reação com oxidante e liberação de energia; combustão completa de hidrocarbonetos gera CO₂ e H₂O.","CH₄ + 2O₂ → CO₂ + 2H₂O.","Na combustão completa do metano forma-se:",["CO₂ e H₂O","Somente H₂","Somente carbono sólido"],0,"Resposta correta: CO₂ e H₂O. Combustão envolve reação com oxidante e liberação de energia; combustão completa de hidrocarbonetos gera CO₂ e H₂O. Exemplo: CH₄ + 2O₂ → CO₂ + 2H₂O."],["Oxidação e redução","Oxidação é aumento de NOX; redução é diminuição de NOX.","Fe²⁺ → Fe³⁺ corresponde a oxidação.","Fe²⁺ → Fe³⁺ representa:",["Redução","Oxidação","Fusão"],1,"Resposta correta: Oxidação. Oxidação é aumento de NOX; redução é diminuição de NOX. Exemplo: Fe²⁺ → Fe³⁺ corresponde a oxidação."],["Agentes oxidante e redutor","Agente oxidante sofre redução; agente redutor sofre oxidação.","Uma espécie que recebe elétrons é reduzida.","O agente oxidante:",["Recebe elétrons na reação","Sempre perde elétrons","Não participa"],0,"Resposta correta: Recebe elétrons na reação. Agente oxidante sofre redução; agente redutor sofre oxidação. Exemplo: Uma espécie que recebe elétrons é reduzida."],["Ácidos e bases","Na definição de Brønsted-Lowry, ácido doa próton e base recebe próton.","HCl doa H⁺ à água formando H₃O⁺.","Segundo Brønsted-Lowry, ácido é doador de:",["Elétron","Próton","Nêutron"],1,"Resposta correta: Próton. Na definição de Brønsted-Lowry, ácido doa próton e base recebe próton. Exemplo: HCl doa H⁺ à água formando H₃O⁺."],["Neutralização","Reação ácido-base pode produzir sal e água, especialmente entre ácido e hidróxido.","HCl + NaOH → NaCl + H₂O.","HCl e NaOH produzem:",["NaCl e H₂O","H₂ e O₂","Somente Cl₂"],0,"Resposta correta: NaCl e H₂O. Reação ácido-base pode produzir sal e água, especialmente entre ácido e hidróxido. Exemplo: HCl + NaOH → NaCl + H₂O."],["Precipitação","Precipitação forma sólido pouco solúvel a partir de espécies em solução.","AgNO₃(aq) + NaCl(aq) → AgCl(s) + NaNO₃(aq).","Qual espécie é precipitado?",["NaNO₃(aq)","AgCl(s)","NaCl(aq)"],1,"Resposta correta: AgCl(s). Precipitação forma sólido pouco solúvel a partir de espécies em solução. Exemplo: AgNO₃(aq) + NaCl(aq) → AgCl(s) + NaNO₃(aq)."],["Mol e quantidade de matéria","Um mol corresponde exatamente a 6,02214076×10²³ entidades elementares.","Um mol de H₂O contém um mol de moléculas de água.","Um mol contém aproximadamente:",["6×10²³ entidades","6×10³ entidades","6 entidades"],0,"Resposta correta: 6×10²³ entidades. Um mol corresponde exatamente a 6,02214076×10²³ entidades elementares. Exemplo: Um mol de H₂O contém um mol de moléculas de água."],["Massa molar","Massa molar relaciona massa e quantidade de matéria.","H₂O tem massa molar aproximada de 18 g/mol.","Dois mols de H₂O têm massa aproximada de:",["9 g","18 g","36 g"],2,"Resposta correta: 36 g. Massa molar relaciona massa e quantidade de matéria. Exemplo: H₂O tem massa molar aproximada de 18 g/mol."],["Reagente limitante","Reagente limitante é o primeiro a se esgotar conforme a proporção estequiométrica.","Se há 2 mol H₂ e 2 mol O₂, H₂ limita a formação de água.","Em 2H₂+O₂→2H₂O, com 2 mol H₂ e 2 mol O₂, limita:",["H₂","O₂","Nenhum"],0,"Resposta correta: H₂. Reagente limitante é o primeiro a se esgotar conforme a proporção estequiométrica. Exemplo: Se há 2 mol H₂ e 2 mol O₂, H₂ limita a formação de água."],["Velocidade das reações","Temperatura, concentração e catalisadores podem alterar velocidade de reação.","Aumentar temperatura geralmente acelera muitas reações.","Catalisador atua principalmente:",["Alterando a velocidade","Mudando número de prótons","Criando massa"],0,"Resposta correta: Alterando a velocidade. Temperatura, concentração e catalisadores podem alterar velocidade de reação. Exemplo: Aumentar temperatura geralmente acelera muitas reações."]],"Química|Ligações":[["Por que átomos se ligam","Ligações químicas resultam de interações eletrostáticas que podem estabilizar sistemas.","Na formação de H₂, dois átomos compartilham densidade eletrônica.","Ligações químicas envolvem principalmente:",["Elétrons e núcleos","Somente nêutrons","Apenas gravidade"],0,"Resposta correta: Elétrons e núcleos. Ligações químicas resultam de interações eletrostáticas que podem estabilizar sistemas. Exemplo: Na formação de H₂, dois átomos compartilham densidade eletrônica."],["Ligação iônica","Ligação iônica envolve atração entre íons de cargas opostas.","NaCl sólido forma rede de Na⁺ e Cl⁻.","A ligação em NaCl é predominantemente:",["Iônica","Metálica","Covalente apolar"],0,"Resposta correta: Iônica. Ligação iônica envolve atração entre íons de cargas opostas. Exemplo: NaCl sólido forma rede de Na⁺ e Cl⁻."],["Ligação covalente","Ligação covalente envolve compartilhamento de pares de elétrons.","Na molécula H₂, os átomos compartilham elétrons.","A molécula H₂ apresenta ligação:",["Iônica","Covalente","Metálica"],1,"Resposta correta: Covalente. Ligação covalente envolve compartilhamento de pares de elétrons. Exemplo: Na molécula H₂, os átomos compartilham elétrons."],["Ligação metálica","Metais apresentam elétrons deslocalizados e ligações coletivas.","O cobre conduz corrente em estado sólido.","Qual tipo de ligação predomina no cobre metálico?",["Metálica","Iônica","Hidrogênio"],0,"Resposta correta: Metálica. Metais apresentam elétrons deslocalizados e ligações coletivas. Exemplo: O cobre conduz corrente em estado sólido."],["Regra do octeto","A regra do octeto é modelo simplificado de estabilidade para diversos elementos representativos.","O neônio possui oito elétrons na camada de valência.","A regra do octeto é:",["Modelo com exceções","Lei universal sem exceções","Regra de prótons"],0,"Resposta correta: Modelo com exceções. A regra do octeto é modelo simplificado de estabilidade para diversos elementos representativos. Exemplo: O neônio possui oito elétrons na camada de valência."],["Estruturas de Lewis","Estruturas de Lewis representam elétrons de valência e ligações.","H–H representa um par eletrônico compartilhado.","Pontos em estruturas de Lewis representam:",["Elétrons de valência","Nêutrons","Massa molar"],0,"Resposta correta: Elétrons de valência. Estruturas de Lewis representam elétrons de valência e ligações. Exemplo: H–H representa um par eletrônico compartilhado."],["Ligações simples, duplas e triplas","Ligações covalentes podem envolver um, dois ou três pares compartilhados.","N₂ apresenta ligação tripla entre os nitrogênios.","Uma ligação dupla compartilha:",["Um par","Dois pares","Três pares"],1,"Resposta correta: Dois pares. Ligações covalentes podem envolver um, dois ou três pares compartilhados. Exemplo: N₂ apresenta ligação tripla entre os nitrogênios."],["Polaridade de ligação","Diferenças de eletronegatividade podem produzir compartilhamento desigual de elétrons.","A ligação H–Cl é polar.","Uma ligação polar apresenta:",["Distribuição desigual de carga","Ausência de elétrons","Sempre íons livres"],0,"Resposta correta: Distribuição desigual de carga. Diferenças de eletronegatividade podem produzir compartilhamento desigual de elétrons. Exemplo: A ligação H–Cl é polar."],["Geometria molecular","Repulsões entre regiões eletrônicas ajudam a prever a geometria molecular.","H₂O possui geometria angular.","A geometria de H₂O é:",["Linear","Angular","Trigonal plana"],1,"Resposta correta: Angular. Repulsões entre regiões eletrônicas ajudam a prever a geometria molecular. Exemplo: H₂O possui geometria angular."],["Polaridade molecular","Polaridade molecular depende de ligações e geometria, que determinam a soma dos dipolos.","CO₂ é linear e apolar, embora tenha ligações polares.","CO₂ é globalmente:",["Polar","Apolar","Iônico"],1,"Resposta correta: Apolar. Polaridade molecular depende de ligações e geometria, que determinam a soma dos dipolos. Exemplo: CO₂ é linear e apolar, embora tenha ligações polares."],["Forças de London","Forças de dispersão de London surgem de flutuações de densidade eletrônica.","Moléculas apolares podem atrair-se por forças de London.","Forças de London ocorrem:",["Apenas em íons","Em todas as partículas polarizáveis","Somente em metais"],1,"Resposta correta: Em todas as partículas polarizáveis. Forças de dispersão de London surgem de flutuações de densidade eletrônica. Exemplo: Moléculas apolares podem atrair-se por forças de London."],["Dipolo-dipolo","Moléculas polares podem apresentar atrações entre dipolos permanentes.","Moléculas de HCl interagem por dipolo-dipolo.","Dipolo-dipolo é comum entre moléculas:",["Polares","Apenas monoatômicas nobres","Sempre iônicas"],0,"Resposta correta: Polares. Moléculas polares podem apresentar atrações entre dipolos permanentes. Exemplo: Moléculas de HCl interagem por dipolo-dipolo."],["Ligação de hidrogênio","Interação de hidrogênio ocorre em condições específicas envolvendo H ligado a N, O ou F e pares eletrônicos aceitadores.","Entre moléculas de água formam-se ligações de hidrogênio.","Qual substância apresenta ligações de hidrogênio entre suas moléculas?",["H₂O","CH₄","CO₂"],0,"Resposta correta: H₂O. Interação de hidrogênio ocorre em condições específicas envolvendo H ligado a N, O ou F e pares eletrônicos aceitadores. Exemplo: Entre moléculas de água formam-se ligações de hidrogênio."],["Solubilidade e polaridade","A compatibilidade entre interações intermoleculares influencia a dissolução.","Água dissolve muitos compostos iônicos e polares.","O etanol mistura-se bem com água porque:",["Pode formar interações polares e ligações de hidrogênio","É metal","É gás nobre"],0,"Resposta correta: Pode formar interações polares e ligações de hidrogênio. A compatibilidade entre interações intermoleculares influencia a dissolução. Exemplo: Água dissolve muitos compostos iônicos e polares."],["Ponto de ebulição","Forças intermoleculares mais intensas frequentemente elevam o ponto de ebulição em comparações adequadas.","Água tem ebulição relativamente elevada para sua massa molar.","Ligações de hidrogênio contribuem para:",["Elevar o ponto de ebulição da água","Eliminar a evaporação","Tornar água metal"],0,"Resposta correta: Elevar o ponto de ebulição da água. Forças intermoleculares mais intensas frequentemente elevam o ponto de ebulição em comparações adequadas. Exemplo: Água tem ebulição relativamente elevada para sua massa molar."],["Materiais e propriedades","Tipo de ligação e estrutura influenciam condutividade, dureza e temperatura de fusão.","NaCl sólido não conduz bem, mas fundido conduz por mobilidade iônica.","NaCl fundido conduz porque:",["Íons podem mover-se","Prótons saem dos núcleos","Moléculas viram elétrons"],0,"Resposta correta: Íons podem mover-se. Tipo de ligação e estrutura influenciam condutividade, dureza e temperatura de fusão. Exemplo: NaCl sólido não conduz bem, mas fundido conduz por mobilidade iônica."]]};
const expandedPhysicsAdvanced:Record<string,[string,string,string,string,[string,string,string],number,string][]> = {"Física|Mecânica":[["Referencial e posição","Posição depende do referencial adotado.","Uma pessoa sentada está em repouso em relação ao ônibus, mas se move em relação à rua.","Uma pessoa sentada em ônibus em movimento está em repouso em relação ao:",["Ônibus","Asfalto","Poste"],0,"Resposta correta: Ônibus. Posição depende do referencial adotado. Exemplo: Uma pessoa sentada está em repouso em relação ao ônibus, mas se move em relação à rua."],["Deslocamento e distância","Distância é o caminho percorrido; deslocamento é a diferença entre posições final e inicial.","Andar 3 m para leste e voltar 3 m dá distância 6 m e deslocamento zero.","Após ir e voltar ao ponto inicial, o deslocamento é:",["6 m","0 m","3 m"],1,"Resposta correta: 0 m. Distância é o caminho percorrido; deslocamento é a diferença entre posições final e inicial. Exemplo: Andar 3 m para leste e voltar 3 m dá distância 6 m e deslocamento zero."],["Velocidade escalar média","Velocidade escalar média é distância total dividida pelo tempo.","Percorrer 100 km em 2 h equivale a 50 km/h.","80 km em 4 h equivalem a:",["20 km/h","40 km/h","320 km/h"],0,"Resposta correta: 20 km/h. Velocidade escalar média é distância total dividida pelo tempo. Exemplo: Percorrer 100 km em 2 h equivale a 50 km/h."],["Conversão de velocidade","Para converter km/h em m/s, divida por 3,6.","72 km/h equivalem a 20 m/s.","36 km/h equivalem a:",["36 m/s","10 m/s","3,6 m/s"],1,"Resposta correta: 10 m/s. Para converter km/h em m/s, divida por 3,6. Exemplo: 72 km/h equivalem a 20 m/s."],["Aceleração média","Aceleração média é variação da velocidade dividida pelo intervalo de tempo.","De 0 a 20 m/s em 5 s: 4 m/s².","De 5 a 15 m/s em 2 s: aceleração de:",["5 m/s²","10 m/s²","20 m/s²"],0,"Resposta correta: 5 m/s². Aceleração média é variação da velocidade dividida pelo intervalo de tempo. Exemplo: De 0 a 20 m/s em 5 s: 4 m/s²."],["Movimento uniforme","No movimento uniforme, a velocidade é constante e a aceleração é nula.","Um móvel a 4 m/s percorre 12 m em 3 s.","A 6 m/s por 5 s, a distância é:",["11 m","30 m","60 m"],1,"Resposta correta: 30 m. No movimento uniforme, a velocidade é constante e a aceleração é nula. Exemplo: Um móvel a 4 m/s percorre 12 m em 3 s."],["Movimento uniformemente variado","Com aceleração constante, a velocidade varia linearmente no tempo.","Partindo do repouso com 2 m/s², após 3 s a velocidade é 6 m/s.","Do repouso com 3 m/s² durante 4 s, a velocidade é:",["7 m/s","12 m/s","24 m/s"],1,"Resposta correta: 12 m/s. Com aceleração constante, a velocidade varia linearmente no tempo. Exemplo: Partindo do repouso com 2 m/s², após 3 s a velocidade é 6 m/s."],["Queda livre","Sem resistência do ar, corpos próximos à superfície terrestre caem com aceleração gravitacional aproximadamente constante.","Usando g = 10 m/s², após 2 s de queda a velocidade é 20 m/s.","Após 3 s de queda a partir do repouso, com g=10 m/s²:",["3 m/s","30 m/s","300 m/s"],1,"Resposta correta: 30 m/s. Sem resistência do ar, corpos próximos à superfície terrestre caem com aceleração gravitacional aproximadamente constante. Exemplo: Usando g = 10 m/s², após 2 s de queda a velocidade é 20 m/s."],["Primeira lei de Newton","Sem força resultante, o corpo mantém repouso ou movimento retilíneo uniforme.","Um disco sobre superfície ideal sem atrito continua em linha reta.","Sem força resultante, um corpo em movimento tende a:",["Parar imediatamente","Manter velocidade","Acelerar"],1,"Resposta correta: Manter velocidade. Sem força resultante, o corpo mantém repouso ou movimento retilíneo uniforme. Exemplo: Um disco sobre superfície ideal sem atrito continua em linha reta."],["Segunda lei de Newton","A força resultante é igual ao produto da massa pela aceleração: F=ma.","2 kg sob 6 N resultantes aceleram a 3 m/s².","Um corpo de 4 kg acelerando a 2 m/s² recebe força resultante de:",["2 N","6 N","8 N"],2,"Resposta correta: 8 N. A força resultante é igual ao produto da massa pela aceleração: F=ma. Exemplo: 2 kg sob 6 N resultantes aceleram a 3 m/s²."],["Terceira lei de Newton","Forças de ação e reação têm módulos iguais, sentidos opostos e atuam em corpos distintos.","Ao empurrar a parede, a parede exerce força sobre sua mão.","Ação e reação atuam:",["No mesmo corpo","Em corpos diferentes","Só em repouso"],1,"Resposta correta: Em corpos diferentes. Forças de ação e reação têm módulos iguais, sentidos opostos e atuam em corpos distintos. Exemplo: Ao empurrar a parede, a parede exerce força sobre sua mão."],["Peso e massa","Massa mede inércia; peso é força gravitacional, calculada por P=mg.","Um corpo de 5 kg sob g=10 m/s² pesa 50 N.","Qual o peso de 3 kg com g=10 m/s²?",["3 N","30 N","300 N"],1,"Resposta correta: 30 N. Massa mede inércia; peso é força gravitacional, calculada por P=mg. Exemplo: Um corpo de 5 kg sob g=10 m/s² pesa 50 N."],["Atrito","Atrito é força de contato que pode se opor ao deslizamento relativo ou à sua tendência.","O atrito entre pneus e estrada ajuda a frear.","Qual força ajuda o pneu a transmitir frenagem ao solo?",["Atrito","Empuxo","Força nuclear"],0,"Resposta correta: Atrito. Atrito é força de contato que pode se opor ao deslizamento relativo ou à sua tendência. Exemplo: O atrito entre pneus e estrada ajuda a frear."],["Trabalho mecânico","Para força constante paralela ao deslocamento, o trabalho é W=F·d.","10 N ao longo de 3 m realizam 30 J.","Uma força paralela de 5 N ao longo de 4 m realiza:",["9 J","20 J","45 J"],1,"Resposta correta: 20 J. Para força constante paralela ao deslocamento, o trabalho é W=F·d. Exemplo: 10 N ao longo de 3 m realizam 30 J."],["Quantidade de movimento","A quantidade de movimento linear é p=mv.","Um corpo de 2 kg a 3 m/s tem p=6 kg·m/s.","Um corpo de 4 kg a 2 m/s tem p:",["2 kg·m/s","6 kg·m/s","8 kg·m/s"],2,"Resposta correta: 8 kg·m/s. A quantidade de movimento linear é p=mv. Exemplo: Um corpo de 2 kg a 3 m/s tem p=6 kg·m/s."],["Impulso e colisões","Impulso da força resultante corresponde à variação da quantidade de movimento.","Uma força média de 10 N durante 2 s produz impulso de 20 N·s.","Força média de 6 N por 3 s produz impulso de:",["2 N·s","9 N·s","18 N·s"],2,"Resposta correta: 18 N·s. Impulso da força resultante corresponde à variação da quantidade de movimento. Exemplo: Uma força média de 10 N durante 2 s produz impulso de 20 N·s."]],"Física|Energia":[["Formas de energia","Energia pode aparecer como cinética, potencial, térmica, química e elétrica.","Uma bateria armazena energia química.","Uma bateria antes de uso armazena principalmente energia:",["Química","Sonora","Luminosa"],0,"Resposta correta: Química. Energia pode aparecer como cinética, potencial, térmica, química e elétrica. Exemplo: Uma bateria armazena energia química."],["Energia cinética","Energia cinética é Ec=mv²/2.","Um corpo de 2 kg a 4 m/s tem Ec=16 J.","Um corpo de 2 kg a 3 m/s tem Ec:",["3 J","9 J","18 J"],1,"Resposta correta: 9 J. Energia cinética é Ec=mv²/2. Exemplo: Um corpo de 2 kg a 4 m/s tem Ec=16 J."],["Energia potencial gravitacional","Perto da superfície terrestre, Ep=mgh.","2 kg a 5 m com g=10 m/s² têm Ep=100 J.","3 kg a 2 m, com g=10 m/s², têm Ep:",["15 J","30 J","60 J"],2,"Resposta correta: 60 J. Perto da superfície terrestre, Ep=mgh. Exemplo: 2 kg a 5 m com g=10 m/s² têm Ep=100 J."],["Energia potencial elástica","Uma mola ideal armazena energia potencial quando deformada.","Ao comprimir uma mola, realiza-se trabalho que pode ser armazenado.","A energia de uma mola comprimida é:",["Elástica","Nuclear","Sonora"],0,"Resposta correta: Elástica. Uma mola ideal armazena energia potencial quando deformada. Exemplo: Ao comprimir uma mola, realiza-se trabalho que pode ser armazenado."],["Conservação da energia","Energia total se conserva em sistema isolado, embora mude de forma.","Em uma queda ideal, energia potencial vira cinética.","Na queda sem resistência, a energia potencial gravitacional:",["Aumenta sempre","Transforma-se em cinética","Desaparece"],1,"Resposta correta: Transforma-se em cinética. Energia total se conserva em sistema isolado, embora mude de forma. Exemplo: Em uma queda ideal, energia potencial vira cinética."],["Energia mecânica","Energia mecânica é a soma das energias cinética e potencial.","Ec=30 J e Ep=20 J totalizam 50 J.","Se Ec=40 J e Ep=10 J, a energia mecânica é:",["30 J","40 J","50 J"],2,"Resposta correta: 50 J. Energia mecânica é a soma das energias cinética e potencial. Exemplo: Ec=30 J e Ep=20 J totalizam 50 J."],["Potência","Potência média é trabalho ou energia transferida por tempo.","Uma máquina transfere 200 J em 4 s: 50 W.","300 J em 5 s equivalem a:",["60 W","150 W","1500 W"],0,"Resposta correta: 60 W. Potência média é trabalho ou energia transferida por tempo. Exemplo: Uma máquina transfere 200 J em 4 s: 50 W."],["Rendimento","Rendimento é energia útil dividida pela energia recebida.","De 100 J recebidos, 80 J úteis correspondem a 80%.","De 200 J recebidos, 150 J úteis representam:",["50%","75%","150%"],1,"Resposta correta: 75%. Rendimento é energia útil dividida pela energia recebida. Exemplo: De 100 J recebidos, 80 J úteis correspondem a 80%."],["Calor e temperatura","Temperatura caracteriza estado térmico; calor é energia transferida devido a diferença de temperatura.","Uma xícara quente transfere calor ao ambiente mais frio.","Calor flui espontaneamente do corpo:",["Mais frio ao mais quente","Mais quente ao mais frio","De menor massa ao maior"],1,"Resposta correta: Mais quente ao mais frio. Temperatura caracteriza estado térmico; calor é energia transferida devido a diferença de temperatura. Exemplo: Uma xícara quente transfere calor ao ambiente mais frio."],["Calor sensível","Sem mudança de fase, Q=mcΔT descreve calor sensível.","Com m=2 kg, c=100 J/kg°C e ΔT=3°C, Q=600 J.","Com m=1 kg, c=100 J/kg°C e ΔT=2°C, Q=",["50 J","200 J","1000 J"],1,"Resposta correta: 200 J. Sem mudança de fase, Q=mcΔT descreve calor sensível. Exemplo: Com m=2 kg, c=100 J/kg°C e ΔT=3°C, Q=600 J."],["Calor latente","Durante mudança de fase a temperatura pode permanecer constante enquanto energia é transferida.","O gelo funde a 0°C sob pressão atmosférica padrão.","A energia associada à fusão é chamada calor:",["Latente","Elétrico","Cinético"],0,"Resposta correta: Latente. Durante mudança de fase a temperatura pode permanecer constante enquanto energia é transferida. Exemplo: O gelo funde a 0°C sob pressão atmosférica padrão."],["Condução térmica","Condução transfere energia térmica por interações microscópicas, sem transporte macroscópico de matéria.","Uma colher metálica aquece ao ficar em líquido quente.","O aquecimento ao longo de uma colher metálica ocorre principalmente por:",["Condução","Convecção","Refração"],0,"Resposta correta: Condução. Condução transfere energia térmica por interações microscópicas, sem transporte macroscópico de matéria. Exemplo: Uma colher metálica aquece ao ficar em líquido quente."],["Convecção térmica","Convecção envolve movimento de fluidos e transporte de energia.","Água aquecida no fundo de uma panela pode subir.","Qual meio permite convecção?",["Fluidos","Apenas vácuo","Somente sólidos rígidos"],0,"Resposta correta: Fluidos. Convecção envolve movimento de fluidos e transporte de energia. Exemplo: Água aquecida no fundo de uma panela pode subir."],["Radiação térmica","Radiação transfere energia por ondas eletromagnéticas, inclusive no vácuo.","A energia solar chega à Terra atravessando o espaço.","A transferência de energia do Sol à Terra ocorre por:",["Condução","Radiação","Convecção no vácuo"],1,"Resposta correta: Radiação. Radiação transfere energia por ondas eletromagnéticas, inclusive no vácuo. Exemplo: A energia solar chega à Terra atravessando o espaço."],["Fontes renováveis","Fontes renováveis se recompõem em escalas humanas, embora possam ter impactos ambientais.","Vento movimenta turbinas eólicas.","Qual fonte é renovável?",["Vento","Carvão mineral","Petróleo"],0,"Resposta correta: Vento. Fontes renováveis se recompõem em escalas humanas, embora possam ter impactos ambientais. Exemplo: Vento movimenta turbinas eólicas."],["Matriz energética","Matriz energética representa as fontes usadas em um território para suprir demandas de energia.","Eletricidade é parte do consumo energético total de um país.","Matriz energética considera:",["Só eletricidade","Diversas fontes e usos","Apenas gasolina"],1,"Resposta correta: Diversas fontes e usos. Matriz energética representa as fontes usadas em um território para suprir demandas de energia. Exemplo: Eletricidade é parte do consumo energético total de um país."]],"Física|Eletricidade":[["Carga elétrica","Prótons têm carga positiva e elétrons têm carga negativa.","Um corpo pode eletrizar-se ao ganhar ou perder elétrons.","O elétron tem carga:",["Positiva","Negativa","Nula"],1,"Resposta correta: Negativa. Prótons têm carga positiva e elétrons têm carga negativa. Exemplo: Um corpo pode eletrizar-se ao ganhar ou perder elétrons."],["Eletrização por atrito","Ao atritar certos materiais, elétrons podem ser transferidos entre eles.","Um balão atritado pode atrair pequenos pedaços de papel.","A eletrização por atrito envolve transferência de:",["Prótons do núcleo","Elétrons","Nêutrons"],1,"Resposta correta: Elétrons. Ao atritar certos materiais, elétrons podem ser transferidos entre eles. Exemplo: Um balão atritado pode atrair pequenos pedaços de papel."],["Condutores e isolantes","Condutores permitem mobilidade de cargas; isolantes dificultam seu movimento.","Cobre é condutor; borracha seca é isolante em condições usuais.","Qual material é bom condutor?",["Cobre","Borracha seca","Vidro"],0,"Resposta correta: Cobre. Condutores permitem mobilidade de cargas; isolantes dificultam seu movimento. Exemplo: Cobre é condutor; borracha seca é isolante em condições usuais."],["Corrente elétrica","Corrente é a quantidade de carga que atravessa uma seção por unidade de tempo: I=Q/t.","10 C em 2 s correspondem a 5 A.","12 C em 3 s equivalem a:",["4 A","9 A","36 A"],0,"Resposta correta: 4 A. Corrente é a quantidade de carga que atravessa uma seção por unidade de tempo: I=Q/t. Exemplo: 10 C em 2 s correspondem a 5 A."],["Tensão elétrica","Tensão é diferença de potencial elétrico entre dois pontos.","Uma pilha pode fornecer diferença de potencial de 1,5 V.","A unidade de tensão é:",["Ampere","Volt","Ohm"],1,"Resposta correta: Volt. Tensão é diferença de potencial elétrico entre dois pontos. Exemplo: Uma pilha pode fornecer diferença de potencial de 1,5 V."],["Resistência elétrica","Resistência elétrica mede oposição à corrente em determinadas condições.","Um resistor de 10 Ω limita a corrente conforme a tensão aplicada.","A unidade de resistência é:",["Ohm","Watt","Coulomb"],0,"Resposta correta: Ohm. Resistência elétrica mede oposição à corrente em determinadas condições. Exemplo: Um resistor de 10 Ω limita a corrente conforme a tensão aplicada."],["Lei de Ohm","Em resistor ôhmico, U=RI.","Com R=4 Ω e I=2 A, U=8 V.","Com R=3 Ω e I=4 A, a tensão é:",["7 V","12 V","24 V"],1,"Resposta correta: 12 V. Em resistor ôhmico, U=RI. Exemplo: Com R=4 Ω e I=2 A, U=8 V."],["Associação em série","Resistores em série são percorridos pela mesma corrente; suas resistências se somam.","2 Ω e 3 Ω em série equivalem a 5 Ω.","4 Ω e 6 Ω em série equivalem a:",["2 Ω","10 Ω","24 Ω"],1,"Resposta correta: 10 Ω. Resistores em série são percorridos pela mesma corrente; suas resistências se somam. Exemplo: 2 Ω e 3 Ω em série equivalem a 5 Ω."],["Associação em paralelo","Resistores em paralelo compartilham a mesma tensão; a resistência equivalente é menor que a menor resistência individual.","Dois resistores iguais de 6 Ω em paralelo equivalem a 3 Ω.","Dois resistores de 8 Ω em paralelo equivalem a:",["4 Ω","8 Ω","16 Ω"],0,"Resposta correta: 4 Ω. Resistores em paralelo compartilham a mesma tensão; a resistência equivalente é menor que a menor resistência individual. Exemplo: Dois resistores iguais de 6 Ω em paralelo equivalem a 3 Ω."],["Potência elétrica","Potência elétrica pode ser calculada por P=UI.","Uma lâmpada sob 12 V com 2 A consome 24 W.","Sob 10 V e 3 A, a potência é:",["13 W","30 W","300 W"],1,"Resposta correta: 30 W. Potência elétrica pode ser calculada por P=UI. Exemplo: Uma lâmpada sob 12 V com 2 A consome 24 W."],["Energia elétrica consumida","Energia consumida é potência multiplicada pelo tempo.","Um aparelho de 1 kW por 2 h consome 2 kWh.","Um aparelho de 2 kW por 3 h consome:",["5 kWh","6 kWh","9 kWh"],1,"Resposta correta: 6 kWh. Energia consumida é potência multiplicada pelo tempo. Exemplo: Um aparelho de 1 kW por 2 h consome 2 kWh."],["Circuito aberto e fechado","Circuito fechado permite caminho para corrente; aberto interrompe esse caminho.","Um interruptor desligado pode abrir o circuito.","Para a lâmpada acender, o circuito deve estar:",["Aberto","Fechado","Sem fonte"],1,"Resposta correta: Fechado. Circuito fechado permite caminho para corrente; aberto interrompe esse caminho. Exemplo: Um interruptor desligado pode abrir o circuito."],["Curto-circuito","Curto-circuito cria caminho de baixa resistência e pode causar corrente excessiva.","Proteções interrompem correntes perigosas em falhas.","O curto-circuito pode provocar:",["Sobrecorrente","Ausência de corrente sempre","Aumento da resistência infinita"],0,"Resposta correta: Sobrecorrente. Curto-circuito cria caminho de baixa resistência e pode causar corrente excessiva. Exemplo: Proteções interrompem correntes perigosas em falhas."],["Fusíveis e disjuntores","Dispositivos de proteção interrompem circuitos em condições de corrente inadequada.","Um disjuntor pode desligar ao detectar sobrecorrente.","Qual dispositivo protege contra sobrecorrente?",["Disjuntor","Capacitor isolado","Ímã decorativo"],0,"Resposta correta: Disjuntor. Dispositivos de proteção interrompem circuitos em condições de corrente inadequada. Exemplo: Um disjuntor pode desligar ao detectar sobrecorrente."],["Campo magnético","Correntes elétricas e ímãs estão associados a campos magnéticos.","Uma bússola responde ao campo magnético terrestre.","Uma bússola orienta-se pelo campo:",["Magnético","Térmico","Gravitacional apenas"],0,"Resposta correta: Magnético. Correntes elétricas e ímãs estão associados a campos magnéticos. Exemplo: Uma bússola responde ao campo magnético terrestre."],["Indução eletromagnética","Variações do fluxo magnético através de um circuito podem induzir tensão elétrica.","Geradores usam indução para converter energia mecânica em elétrica.","Um gerador elétrico convencional utiliza:",["Indução eletromagnética","Fusão nuclear obrigatória","Atrito como única fonte"],0,"Resposta correta: Indução eletromagnética. Variações do fluxo magnético através de um circuito podem induzir tensão elétrica. Exemplo: Geradores usam indução para converter energia mecânica em elétrica."]],"Física|Óptica":[["Propagação retilínea","Em meio homogêneo e transparente, a luz se propaga aproximadamente em linha reta.","Sombras surgem porque objetos opacos bloqueiam trajetórias da luz.","A formação de sombras está ligada à:",["Propagação retilínea","Convecção","Eletrólise"],0,"Resposta correta: Propagação retilínea. Em meio homogêneo e transparente, a luz se propaga aproximadamente em linha reta. Exemplo: Sombras surgem porque objetos opacos bloqueiam trajetórias da luz."],["Fontes luminosas","Fontes primárias emitem luz; corpos iluminados refletem luz recebida.","O Sol é fonte primária; a Lua reflete luz solar.","Qual é fonte primária?",["Lua","Sol","Espelho"],1,"Resposta correta: Sol. Fontes primárias emitem luz; corpos iluminados refletem luz recebida. Exemplo: O Sol é fonte primária; a Lua reflete luz solar."],["Meios transparentes","Materiais transparentes transmitem luz com pouca dispersão; translúcidos dispersam; opacos bloqueiam.","Vidro limpo é transparente; papel vegetal é translúcido.","Qual material é geralmente opaco?",["Parede de concreto","Vidro limpo","Ar"],0,"Resposta correta: Parede de concreto. Materiais transparentes transmitem luz com pouca dispersão; translúcidos dispersam; opacos bloqueiam. Exemplo: Vidro limpo é transparente; papel vegetal é translúcido."],["Reflexão da luz","Na reflexão, o ângulo de incidência é igual ao de reflexão, medidos em relação à normal.","Um raio incidindo a 30° da normal reflete a 30°.","Incidência de 40° da normal gera reflexão de:",["20°","40°","80°"],1,"Resposta correta: 40°. Na reflexão, o ângulo de incidência é igual ao de reflexão, medidos em relação à normal. Exemplo: Um raio incidindo a 30° da normal reflete a 30°."],["Espelho plano","Espelho plano forma imagem virtual, direita e do mesmo tamanho do objeto.","A imagem parece estar atrás do espelho à mesma distância do objeto.","Em espelho plano, a imagem é:",["Virtual e direita","Real e invertida","Sempre ampliada"],0,"Resposta correta: Virtual e direita. Espelho plano forma imagem virtual, direita e do mesmo tamanho do objeto. Exemplo: A imagem parece estar atrás do espelho à mesma distância do objeto."],["Espelhos côncavos","Espelhos côncavos podem produzir imagens reais ou virtuais conforme a posição do objeto.","Objeto próximo ao espelho côncavo, dentro do foco, pode ter imagem ampliada e virtual.","O espelho côncavo pode formar imagem:",["Apenas virtual","Real ou virtual","Sempre do mesmo tamanho"],1,"Resposta correta: Real ou virtual. Espelhos côncavos podem produzir imagens reais ou virtuais conforme a posição do objeto. Exemplo: Objeto próximo ao espelho côncavo, dentro do foco, pode ter imagem ampliada e virtual."],["Espelhos convexos","Espelhos convexos formam imagens virtuais, direitas e reduzidas de objetos reais.","Retrovisores convexos ampliam o campo de visão.","Espelho convexo costuma formar imagem:",["Reduzida e direita","Real e ampliada","Invertida e real"],0,"Resposta correta: Reduzida e direita. Espelhos convexos formam imagens virtuais, direitas e reduzidas de objetos reais. Exemplo: Retrovisores convexos ampliam o campo de visão."],["Refração","Refração ocorre quando a luz muda de velocidade ao passar entre meios.","Um canudo na água pode parecer quebrado devido à refração.","O efeito do canudo aparentemente quebrado é:",["Refração","Indução","Condução"],0,"Resposta correta: Refração. Refração ocorre quando a luz muda de velocidade ao passar entre meios. Exemplo: Um canudo na água pode parecer quebrado devido à refração."],["Índice de refração","Índice de refração absoluto é n=c/v, relacionando velocidade no vácuo e no meio.","Se a luz se move a c/2 em um meio, n=2.","Se v=c/1,5, o índice é:",["0,5","1,5","3"],1,"Resposta correta: 1,5. Índice de refração absoluto é n=c/v, relacionando velocidade no vácuo e no meio. Exemplo: Se a luz se move a c/2 em um meio, n=2."],["Lentes convergentes","Lentes convergentes podem reunir raios paralelos próximos ao eixo em um foco.","Uma lupa usa lente convergente para ampliar objetos próximos.","Qual dispositivo usa lente convergente?",["Lupa","Espelho plano","Parede"],0,"Resposta correta: Lupa. Lentes convergentes podem reunir raios paralelos próximos ao eixo em um foco. Exemplo: Uma lupa usa lente convergente para ampliar objetos próximos."],["Lentes divergentes","Lentes divergentes espalham raios paralelos, que parecem vir de um foco virtual.","Certos óculos para miopia usam lentes divergentes.","Uma lente divergente tende a:",["Convergir raios paralelos em foco real","Espalhar raios paralelos","Refletir toda a luz"],1,"Resposta correta: Espalhar raios paralelos. Lentes divergentes espalham raios paralelos, que parecem vir de um foco virtual. Exemplo: Certos óculos para miopia usam lentes divergentes."],["Formação de imagens","A posição do objeto em relação ao foco altera a imagem em lentes convergentes.","Objeto além do dobro da distância focal pode formar imagem real reduzida.","Uma imagem real de lente convergente pode ser projetada em:",["Tela","Somente espelho","Apenas retina sem luz"],0,"Resposta correta: Tela. A posição do objeto em relação ao foco altera a imagem em lentes convergentes. Exemplo: Objeto além do dobro da distância focal pode formar imagem real reduzida."],["Dispersão da luz","A dispersão separa componentes de luz conforme sua interação com um meio.","Um prisma pode separar luz branca em cores.","O prisma pode produzir:",["Dispersão","Corrente elétrica","Convecção"],0,"Resposta correta: Dispersão. A dispersão separa componentes de luz conforme sua interação com um meio. Exemplo: Um prisma pode separar luz branca em cores."],["Cores e reflexão","A cor percebida depende da luz incidente e da luz refletida ou transmitida.","Uma superfície vermelha sob luz branca reflete preferencialmente componentes vermelhos.","Um objeto vermelho sob luz branca tende a refletir:",["Vermelho","Somente azul","Nenhuma luz"],0,"Resposta correta: Vermelho. A cor percebida depende da luz incidente e da luz refletida ou transmitida. Exemplo: Uma superfície vermelha sob luz branca reflete preferencialmente componentes vermelhos."],["Olho humano","A retina contém fotorreceptores que convertem luz em sinais neurais.","A córnea e o cristalino ajudam a focalizar luz na retina.","Qual estrutura detecta a luz?",["Retina","Tímpano","Fêmur"],0,"Resposta correta: Retina. A retina contém fotorreceptores que convertem luz em sinais neurais. Exemplo: A córnea e o cristalino ajudam a focalizar luz na retina."],["Instrumentos ópticos","Microscópios e telescópios usam elementos ópticos para observar objetos em diferentes escalas.","Um telescópio coleta luz de objetos distantes.","Qual instrumento observa astros distantes?",["Telescópio","Termômetro","Barômetro"],0,"Resposta correta: Telescópio. Microscópios e telescópios usam elementos ópticos para observar objetos em diferentes escalas. Exemplo: Um telescópio coleta luz de objetos distantes."]]};
const expandedPortugueseAdvanced:Record<string,[string,string,string,string,[string,string,string],number,string][]> = {"Português|Gramática":[["Ortografia e acentuação","A acentuação distingue a sílaba tônica e segue regras conforme a posição do acento.","Café é oxítona terminada em e e recebe acento.","Qual palavra está corretamente acentuada?",["Cafe","Café","Cafê"],1,"Resposta correta: Café. A acentuação distingue a sílaba tônica e segue regras conforme a posição do acento."],["Substantivos e flexões","Substantivos nomeiam seres, lugares, objetos e conceitos; podem variar em gênero e número.","Cidade é substantivo feminino singular; cidades é plural.","Qual palavra é substantivo?",["Bonito","Correr","Cidade"],2,"Resposta correta: Cidade. Substantivos nomeiam seres, lugares, objetos e conceitos; podem variar em gênero e número."],["Artigos e determinantes","Artigos definidos e indefinidos acompanham substantivos e ajudam a determinar sua referência.","O aluno indica referência definida; um aluno, indefinida.","Qual expressão tem artigo indefinido?",["A escola","Um livro","Os alunos"],1,"Resposta correta: Um livro. Artigos definidos e indefinidos acompanham substantivos e ajudam a determinar sua referência."],["Pronomes pessoais","Pronomes pessoais indicam participantes do discurso e podem substituir nomes.","Ela chegou cedo: ela pode retomar Maria.","Qual é pronome pessoal?",["Ela","Azul","Ontem"],0,"Resposta correta: Ela. Pronomes pessoais indicam participantes do discurso e podem substituir nomes."],["Tempos verbais","Presente, pretérito e futuro situam ações no tempo.","Estudei indica ação passada; estudarei indica ação futura.","Qual verbo está no futuro?",["Estudo","Estudei","Estudarei"],2,"Resposta correta: Estudarei. Presente, pretérito e futuro situam ações no tempo."],["Advérbios","Advérbios podem modificar verbos, adjetivos ou outros advérbios, indicando circunstâncias.","Ela respondeu rapidamente: rapidamente indica modo.","Em 'falou calmamente', o advérbio indica:",["Lugar","Modo","Quantidade de pessoas"],1,"Resposta correta: Modo. Advérbios podem modificar verbos, adjetivos ou outros advérbios, indicando circunstâncias."],["Preposições","Preposições relacionam termos e introduzem complementos ou circunstâncias.","Livro de História: de relaciona os substantivos.","Qual palavra é preposição?",["De","Livro","Feliz"],0,"Resposta correta: De. Preposições relacionam termos e introduzem complementos ou circunstâncias."],["Conjunções","Conjunções conectam orações ou termos e expressam relações lógicas.","Estudou, mas não passou: mas indica oposição.","Qual conjunção expressa oposição?",["Porque","Mas","Portanto"],1,"Resposta correta: Mas. Conjunções conectam orações ou termos e expressam relações lógicas."],["Concordância nominal","Artigos, adjetivos e outros determinantes concordam com o substantivo em gênero e número.","As casas bonitas: todos os termos estão no feminino plural.","Qual expressão apresenta concordância correta?",["As casa bonita","As casas bonitas","Os casas bonitos"],1,"Resposta correta: As casas bonitas. Artigos, adjetivos e outros determinantes concordam com o substantivo em gênero e número."],["Regência verbal","A regência trata da relação entre verbos e seus complementos, incluindo preposições exigidas.","Quem gosta, gosta de algo: gosto de música.","Qual construção está adequada?",["Gosto de música","Gosto música","Gosto à música"],0,"Resposta correta: Gosto de música. A regência trata da relação entre verbos e seus complementos, incluindo preposições exigidas."],["Voz ativa e passiva","Na voz ativa, o sujeito pratica a ação; na passiva, recebe a ação verbal.","O aluno escreveu o texto → O texto foi escrito pelo aluno.","Qual frase está na voz passiva?",["Ana abriu a porta","A porta foi aberta por Ana","Ana está abrindo"],1,"Resposta correta: A porta foi aberta por Ana. Na voz ativa, o sujeito pratica a ação; na passiva, recebe a ação verbal."],["Período simples e composto","Período simples tem uma oração; período composto reúne duas ou mais.","Cheguei e descansei contém duas orações.","Qual período é composto?",["O menino dormiu","Choveu muito","Estudei e aprendi"],2,"Resposta correta: Estudei e aprendi. Período simples tem uma oração; período composto reúne duas ou mais."],["Orações coordenadas","Orações coordenadas são sintaticamente independentes e podem ser ligadas por conjunções.","Queria sair, porém estava chovendo: porém marca adversidade.","Qual conectivo indica conclusão?",["Logo","Mas","Ou"],0,"Resposta correta: Logo. Orações coordenadas são sintaticamente independentes e podem ser ligadas por conjunções."],["Orações subordinadas","Orações subordinadas exercem função sintática em relação a outra oração.","Espero que você venha: que você venha completa o verbo esperar.","Em 'Espero que ele chegue', a oração iniciada por que:",["Completa o sentido de espero","É vocativo","Indica apenas lugar"],0,"Resposta correta: Completa o sentido de espero. Orações subordinadas exercem função sintática em relação a outra oração."]],"Português|Interpretação":[["Localização de informações","Localize palavras-chave no enunciado e encontre o trecho correspondente no texto.","Texto: A feira abre aos sábados. Pergunta: quando abre? Aos sábados.","Se o texto diz 'abre às 8h', qual horário é informado?",["Às 7h","Às 8h","Às 9h"],1,"Resposta correta: Às 8h. Localize palavras-chave no enunciado e encontre o trecho correspondente no texto."],["Sequência de acontecimentos","Reconstrua a ordem de eventos a partir de marcadores temporais.","Primeiro acordou, depois tomou café, por fim saiu.","Qual marcador indica encerramento?",["Primeiro","Enquanto","Por fim"],2,"Resposta correta: Por fim. Reconstrua a ordem de eventos a partir de marcadores temporais."],["Causa e consequência","Causa explica o motivo; consequência apresenta o resultado.","Como choveu, a partida foi adiada.","No exemplo, o adiamento foi:",["Causa","Consequência","Comparação"],1,"Resposta correta: Consequência. Causa explica o motivo; consequência apresenta o resultado."],["Comparação textual","Compare informações para identificar semelhanças e diferenças.","Um texto defende transporte público; outro destaca ciclovias.","Comparar textos exige observar:",["Apenas o tamanho","Pontos comuns e divergentes","Somente o título"],1,"Resposta correta: Pontos comuns e divergentes. Compare informações para identificar semelhanças e diferenças."],["Argumento e evidência","Identifique afirmações e os dados ou exemplos usados para sustentá-las.","A pesquisa aponta aumento da leitura: o dado sustenta uma afirmação.","Qual elemento pode funcionar como evidência?",["Dado verificável","Opinião sem justificativa","Mudança de assunto"],0,"Resposta correta: Dado verificável. Identifique afirmações e os dados ou exemplos usados para sustentá-las."],["Pressupostos","Pressupostos são informações tratadas como dadas por certas escolhas linguísticas.","João voltou a estudar pressupõe que já estudava antes.","Em 'voltou a correr', pressupõe-se que a pessoa:",["Nunca correu","Já correu antes","Não corre agora"],1,"Resposta correta: Já correu antes. Pressupostos são informações tratadas como dadas por certas escolhas linguísticas."],["Ironia","Ironia pode expressar sentido diferente do literal, percebido pelo contexto.","Ao ver um quarto bagunçado, alguém diz: Que organização!","No exemplo, o efeito é de:",["Ironia","Definição científica","Enumeração"],0,"Resposta correta: Ironia. Ironia pode expressar sentido diferente do literal, percebido pelo contexto."],["Metáforas no texto","Metáforas criam sentidos por aproximação entre ideias sem comparação explícita.","A cidade acordou indica movimento e atividade urbana.","Em 'a cidade acordou', há:",["Sentido figurado","Uma cidade dormindo literalmente","Cálculo matemático"],0,"Resposta correta: Sentido figurado. Metáforas criam sentidos por aproximação entre ideias sem comparação explícita."],["Coesão referencial","Identifique a que termo se referem pronomes e expressões de retomada.","Clara encontrou Paula. Ela sorriu: o referente de ela pode ser ambíguo.","Quando um pronome admite dois referentes, há:",["Clareza total","Ambiguidade","Rima"],1,"Resposta correta: Ambiguidade. Identifique a que termo se referem pronomes e expressões de retomada."],["Conectivos argumentativos","Conectivos sinalizam relações como causa, contraste e conclusão.","Portanto indica conclusão de um raciocínio.","Qual conectivo indica contraste?",["Entretanto","Assim","Além disso"],0,"Resposta correta: Entretanto. Conectivos sinalizam relações como causa, contraste e conclusão."],["Tese do autor","A tese expressa a posição defendida no texto argumentativo.","A mobilidade urbana deve priorizar o transporte coletivo é uma tese.","Qual frase expressa posição defendida?",["Existem ônibus","O transporte público deve ser priorizado","A cidade tem ruas"],1,"Resposta correta: O transporte público deve ser priorizado. A tese expressa a posição defendida no texto argumentativo."],["Público-alvo","Vocabulário, suporte e tom ajudam a identificar para quem o texto foi produzido.","Um aviso escolar dirigido às famílias usa linguagem orientadora.","O público-alvo é:",["Quem o texto pretende alcançar","Sempre o autor","Apenas quem discorda"],0,"Resposta correta: Quem o texto pretende alcançar. Vocabulário, suporte e tom ajudam a identificar para quem o texto foi produzido."],["Gêneros textuais","Reconheça propósito e organização de notícia, propaganda, receita e artigo de opinião.","Notícia relata fatos de interesse público; artigo de opinião defende ponto de vista.","Qual gênero costuma defender uma tese?",["Artigo de opinião","Lista de compras","Calendário"],0,"Resposta correta: Artigo de opinião. Reconheça propósito e organização de notícia, propaganda, receita e artigo de opinião."],["Síntese e resumo","Resumir é preservar ideias essenciais sem introduzir informações novas.","Um bom resumo identifica tema, argumentos centrais e conclusão.","O resumo deve:",["Inventar fatos","Preservar o essencial","Copiar cada frase"],1,"Resposta correta: Preservar o essencial. Resumir é preservar ideias essenciais sem introduzir informações novas."]],"Português|Redação":[["Planejamento do texto","Antes de redigir, organize tese, argumentos e conclusão em um roteiro breve.","Tese: leitura é importante. Argumentos: vocabulário e pensamento crítico.","O planejamento ajuda a:",["Organizar ideias","Eliminar a revisão","Dispensar argumentos"],0,"Resposta correta: Organizar ideias. Antes de redigir, organize tese, argumentos e conclusão em um roteiro breve."],["Adequação ao gênero","Cada gênero textual possui finalidade e estrutura próprias.","Uma carta formal exige tratamento diferente de um bilhete informal.","A estrutura de um texto depende:",["Do gênero e objetivo","Somente do tamanho","Apenas do título"],0,"Resposta correta: Do gênero e objetivo. Cada gênero textual possui finalidade e estrutura próprias."],["Parágrafo argumentativo","Desenvolva uma ideia principal por parágrafo e explique sua relação com a tese.","Ideia: bibliotecas ampliam acesso. Explicação: oferecem livros gratuitamente.","Um parágrafo argumentativo precisa:",["Ideia e desenvolvimento","Somente uma palavra","Apenas citação"],0,"Resposta correta: Ideia e desenvolvimento. Desenvolva uma ideia principal por parágrafo e explique sua relação com a tese."],["Exemplificação","Exemplos concretos esclarecem argumentos e devem estar ligados ao tema.","Ao discutir mobilidade, citar uma ciclovia pode ilustrar uma política pública.","Um exemplo adequado deve:",["Ser pertinente","Ser inventado como fato","Contradizer sem explicar"],0,"Resposta correta: Ser pertinente. Exemplos concretos esclarecem argumentos e devem estar ligados ao tema."],["Citação e repertório","Referências históricas, culturais ou científicas precisam ser pertinentes e corretamente atribuídas.","Uma referência à Constituição pode fundamentar debate sobre direitos.","Repertório produtivo é aquele que:",["Relaciona-se ao argumento","É sempre longo","Substitui a tese"],0,"Resposta correta: Relaciona-se ao argumento. Referências históricas, culturais ou científicas precisam ser pertinentes e corretamente atribuídas."],["Contra-argumentação","Reconhecer uma objeção e respondê-la pode fortalecer a defesa da tese.","Embora a medida tenha custos, seus benefícios sociais justificam o investimento.","O conectivo embora introduz:",["Concessão","Conclusão","Adição"],0,"Resposta correta: Concessão. Reconhecer uma objeção e respondê-la pode fortalecer a defesa da tese."],["Progressão temática","O texto deve avançar a cada parágrafo, evitando repetir a mesma ideia.","Após apresentar o problema, explique causas e consequências.","Progressão temática significa:",["Avançar nas ideias","Repetir a introdução","Trocar de tema sem ligação"],0,"Resposta correta: Avançar nas ideias. O texto deve avançar a cada parágrafo, evitando repetir a mesma ideia."],["Conectivos de causa","Conectivos causais esclarecem por que algo acontece.","A atividade foi cancelada porque choveu.","Qual conectivo indica causa?",["Porque","Porém","Portanto"],0,"Resposta correta: Porque. Conectivos causais esclarecem por que algo acontece."],["Conectivos de conclusão","Conectivos conclusivos indicam resultado de um raciocínio.","Os dados apontam melhora; portanto, a medida foi eficaz.","Qual conectivo indica conclusão?",["Entretanto","Portanto","Embora"],1,"Resposta correta: Portanto. Conectivos conclusivos indicam resultado de um raciocínio."],["Clareza e objetividade","Prefira frases precisas, elimine ambiguidades e evite repetições desnecessárias.","Em vez de 'coisa boa', especifique 'melhoria no atendimento'.","Qual escolha melhora a clareza?",["Termos específicos","Frases vagas","Contradições"],0,"Resposta correta: Termos específicos. Prefira frases precisas, elimine ambiguidades e evite repetições desnecessárias."],["Norma-padrão","Em contextos formais, revise concordância, regência, ortografia e pontuação.","Os estudantes participaram está de acordo com a concordância verbal.","Qual frase está adequada à norma-padrão?",["Os aluno chegou","Os alunos chegaram","Os alunos chegou"],1,"Resposta correta: Os alunos chegaram. Em contextos formais, revise concordância, regência, ortografia e pontuação."],["Título e apresentação","Quando exigido, o título deve dialogar com o conteúdo e não substituir a tese.","Título: Desafios da mobilidade urbana; texto discute transporte e acesso.","Um título eficaz deve:",["Relacionar-se ao tema","Contradizer o texto","Ser sempre uma pergunta"],0,"Resposta correta: Relacionar-se ao tema. Quando exigido, o título deve dialogar com o conteúdo e não substituir a tese."],["Revisão estrutural","Confira se introdução, desenvolvimento e conclusão cumprem suas funções.","Verifique se cada argumento sustenta a tese e se a conclusão fecha o raciocínio.","Na revisão estrutural, confira:",["Coerência entre partes","Somente fonte tipográfica","Apenas número de linhas"],0,"Resposta correta: Coerência entre partes. Confira se introdução, desenvolvimento e conclusão cumprem suas funções."],["Reescrita orientada","Reescrever envolve melhorar trechos com base em critérios de clareza, coesão e precisão.","Troque 'isso é ruim' por uma explicação do impacto específico.","Reescrever bem significa:",["Melhorar o texto com critérios","Trocar todas as palavras","Apagar os argumentos"],0,"Resposta correta: Melhorar o texto com critérios. Reescrever envolve melhorar trechos com base em critérios de clareza, coesão e precisão."]],"Português|Literatura":[["Poesia e verso","Poemas podem organizar linguagem em versos e estrofes, com ou sem rima.","Uma estrofe é um conjunto de versos.","Como se chama um conjunto de versos?",["Parágrafo jornalístico","Estrofe","Capítulo"],1,"Resposta correta: Estrofe. Poemas podem organizar linguagem em versos e estrofes, com ou sem rima."],["Ritmo e sonoridade","Repetições, pausas e acentos criam efeitos sonoros na poesia.","A aliteração repete sons consonantais próximos.","A repetição de sons consonantais é:",["Aliteração","Hipérbole","Antítese"],0,"Resposta correta: Aliteração. Repetições, pausas e acentos criam efeitos sonoros na poesia."],["Conto","O conto é narrativa geralmente breve, com recorte concentrado de acontecimentos.","Um conto pode apresentar um conflito central e poucos personagens.","Qual característica é comum ao conto?",["Brevidade narrativa","Obrigação de rimar","Ausência de narrador"],0,"Resposta correta: Brevidade narrativa. O conto é narrativa geralmente breve, com recorte concentrado de acontecimentos."],["Romance","O romance costuma desenvolver narrativas mais extensas, com múltiplas situações e personagens.","Um romance pode acompanhar transformações de personagens ao longo do tempo.","Em geral, o romance permite:",["Desenvolvimento narrativo amplo","Apenas um verso","Somente diálogos teatrais"],0,"Resposta correta: Desenvolvimento narrativo amplo. O romance costuma desenvolver narrativas mais extensas, com múltiplas situações e personagens."],["Crônica","A crônica frequentemente aborda experiências cotidianas com observação e reflexão.","Um texto sobre um encontro inesperado no ônibus pode ser crônica.","A crônica costuma explorar:",["Cotidiano","Tabela periódica","Demonstração algébrica"],0,"Resposta correta: Cotidiano. A crônica frequentemente aborda experiências cotidianas com observação e reflexão."],["Teatro e rubricas","Textos dramáticos apresentam falas e indicações cênicas chamadas rubricas.","(Entra lentamente.) é uma rubrica de cena.","Uma rubrica indica:",["Ação ou orientação cênica","Rima obrigatória","Narrador onisciente"],0,"Resposta correta: Ação ou orientação cênica. Textos dramáticos apresentam falas e indicações cênicas chamadas rubricas."],["Romantismo","O Romantismo valorizou subjetividade, emoção e, em contextos nacionais, temas identitários.","Na literatura brasileira, o indianismo apareceu em parte da produção romântica.","Qual traço é associado ao Romantismo?",["Valorização da subjetividade","Exclusão da emoção","Obrigação de linguagem técnica"],0,"Resposta correta: Valorização da subjetividade. O Romantismo valorizou subjetividade, emoção e, em contextos nacionais, temas identitários."],["Realismo","O Realismo explorou observação crítica de comportamentos e relações sociais.","Narrativas realistas podem questionar convenções sociais.","Qual característica é comum ao Realismo?",["Crítica social","Idealização obrigatória","Ausência de personagens"],0,"Resposta correta: Crítica social. O Realismo explorou observação crítica de comportamentos e relações sociais."],["Modernismo brasileiro","O Modernismo renovou linguagens e questionou convenções estéticas.","A Semana de Arte Moderna de 1922 tornou-se um marco simbólico do movimento.","Qual evento se associa ao Modernismo brasileiro?",["Semana de Arte Moderna de 1922","Independência de 1822","Proclamação de 1889"],0,"Resposta correta: Semana de Arte Moderna de 1922. O Modernismo renovou linguagens e questionou convenções estéticas."],["Barroco","O Barroco frequentemente explora contrastes, tensões e linguagem elaborada.","Antíteses podem aproximar ideias opostas em um poema barroco.","Qual recurso combina com o Barroco?",["Contrastes","Manual de instalação","Neutralidade obrigatória"],0,"Resposta correta: Contrastes. O Barroco frequentemente explora contrastes, tensões e linguagem elaborada."],["Arcadismo","O Arcadismo valorizou ideais clássicos e imagens de vida pastoril.","Poemas árcades podem idealizar a simplicidade do campo.","Qual cenário é recorrente no Arcadismo?",["Vida pastoril","Fábrica espacial","Laboratório digital"],0,"Resposta correta: Vida pastoril. O Arcadismo valorizou ideais clássicos e imagens de vida pastoril."],["Simbolismo","O Simbolismo privilegiou sugestão, musicalidade e imagens sensoriais.","Um poema simbolista pode explorar sinestesia e atmosfera subjetiva.","Qual recurso se associa ao Simbolismo?",["Sugestão sensorial","Relatório contábil","Equação química"],0,"Resposta correta: Sugestão sensorial. O Simbolismo privilegiou sugestão, musicalidade e imagens sensoriais."],["Intertextualidade","Intertextualidade ocorre quando um texto dialoga com outros textos.","Uma paródia transforma criticamente uma obra conhecida.","Qual fenômeno ocorre em uma paródia?",["Diálogo com outro texto","Ausência de referências","Apenas tradução literal"],0,"Resposta correta: Diálogo com outro texto. Intertextualidade ocorre quando um texto dialoga com outros textos."],["Análise de personagem","Personagens podem ser construídas por ações, falas, relações e perspectivas narrativas.","Uma personagem muda de atitude após um conflito, revelando transformação.","Para analisar uma personagem, observe:",["Ações e falas","Só o número de páginas","Apenas o título"],0,"Resposta correta: Ações e falas. Personagens podem ser construídas por ações, falas, relações e perspectivas narrativas."]]};
const expandedEnglish:Record<string,[string,string,string,string,[string,string,string],number,string][]> = {"Inglês|Vocabulário":[["Greetings","Greetings are expressions used to greet someone.","Hello! Good morning!","How do you say 'bom dia'?",["Good night","Good morning","Goodbye"],1,"Resposta correta: Good morning. Greetings are expressions used to greet someone. Exemplo: Hello! Good morning!"],["Introductions","Use 'My name is' to introduce yourself.","My name is Ana.","Which sentence introduces a person?",["My name is Lucas.","I am hungry.","See you later."],0,"Resposta correta: My name is Lucas.. Use 'My name is' to introduce yourself. Exemplo: My name is Ana."],["Numbers","English numbers help express quantities and ages.","Twenty-one means 21.","How do you write 15 in English?",["Fifty","Fifteen","Five"],1,"Resposta correta: Fifteen. English numbers help express quantities and ages. Exemplo: Twenty-one means 21."],["Days of the week","The days of the week begin with capital letters in English.","Monday, Tuesday, Wednesday.","Which word is a day of the week?",["January","Monday","Morning"],1,"Resposta correta: Monday. The days of the week begin with capital letters in English. Exemplo: Monday, Tuesday, Wednesday."],["Family members","Family vocabulary describes relatives.","Mother means mãe; brother means irmão.","What does 'sister' mean?",["Irmã","Prima","Avó"],0,"Resposta correta: Irmã. Family vocabulary describes relatives. Exemplo: Mother means mãe; brother means irmão."],["Food and drinks","Food vocabulary helps when ordering meals.","Water means água; bread means pão.","Which word means 'água'?",["Bread","Water","Milk"],1,"Resposta correta: Water. Food vocabulary helps when ordering meals. Exemplo: Water means água; bread means pão."]],"Inglês|Conversação":[["Asking how someone is","Use 'How are you?' to ask how someone feels.","How are you? I'm fine, thanks.","Which answer fits 'How are you?'",["I'm fine, thanks.","It's Monday.","At seven."],0,"Resposta correta: I'm fine, thanks.. Use 'How are you?' to ask how someone feels. Exemplo: How are you? I'm fine, thanks."],["Ordering food","Use 'I'd like' to request food politely.","I'd like a sandwich, please.","Which phrase is a polite request?",["I'd like a coffee, please.","Coffee yesterday.","Where coffee? "],0,"Resposta correta: I'd like a coffee, please.. Use 'I'd like' to request food politely. Exemplo: I'd like a sandwich, please."],["Asking directions","Use 'Where is...?' to ask for a place.","Where is the train station?","How do you ask where the bank is?",["What is bank?","Where is the bank?","When is bank?"],1,"Resposta correta: Where is the bank?. Use 'Where is...?' to ask for a place. Exemplo: Where is the train station?"],["Shopping","Use 'How much is it?' to ask the price.","How much is this shirt?","Which question asks the price?",["How old are you?","How much is it?","Where are you from?"],1,"Resposta correta: How much is it?. Use 'How much is it?' to ask the price. Exemplo: How much is this shirt?"],["Making plans","Use 'Let's' to suggest an activity.","Let's study together tomorrow.","Which sentence suggests an activity?",["Let's go to the park.","I went yesterday.","This is my book."],0,"Resposta correta: Let's go to the park.. Use 'Let's' to suggest an activity. Exemplo: Let's study together tomorrow."],["Talking about routines","Use the simple present to describe habits.","I wake up at seven every day.","Which sentence describes a routine?",["I wake up at seven every day.","I woke up once.","I will leave next year."],0,"Resposta correta: I wake up at seven every day.. Use the simple present to describe habits. Exemplo: I wake up at seven every day."]],"Inglês|Gramática":[["Subject pronouns","Subject pronouns replace names as sentence subjects.","She is a teacher. They are students.","Which pronoun replaces 'Maria'?",["He","She","It"],1,"Resposta correta: She. Subject pronouns replace names as sentence subjects. Exemplo: She is a teacher. They are students."],["Verb to be","Use am with I, is with he/she/it, and are with you/we/they.","I am happy. She is ready.","Complete: They ___ students.",["is","am","are"],2,"Resposta correta: are. Use am with I, is with he/she/it, and are with you/we/they. Exemplo: I am happy. She is ready."],["Articles","Use 'a' before a consonant sound and 'an' before a vowel sound.","A book; an apple.","Choose the correct phrase:",["a apple","an apple","an book"],1,"Resposta correta: an apple. Use 'a' before a consonant sound and 'an' before a vowel sound. Exemplo: A book; an apple."],["Simple present","With he, she and it, most verbs add -s in affirmative simple present.","She works every day.","Complete: He ___ English.",["study","studies","studying"],1,"Resposta correta: studies. With he, she and it, most verbs add -s in affirmative simple present. Exemplo: She works every day."],["Present continuous","Use am/is/are plus verb-ing for actions happening now.","They are reading now.","Complete: She ___ cooking.",["is","are","am"],0,"Resposta correta: is. Use am/is/are plus verb-ing for actions happening now. Exemplo: They are reading now."],["Simple past","Regular verbs often end in -ed in the simple past; irregular verbs have distinct forms.","I visited my friend yesterday.","Which sentence is in the simple past?",["I visit every day.","I visited yesterday.","I am visiting now."],1,"Resposta correta: I visited yesterday.. Regular verbs often end in -ed in the simple past; irregular verbs have distinct forms. Exemplo: I visited my friend yesterday."]]};
const expandedHumanities:Record<string,[string,string,string,string,[string,string,string],number,string][]> = {"História|História antiga":[["Civilizações fluviais","Sociedades antigas se desenvolveram próximas a rios que favoreciam agricultura e transporte.","O Egito antigo se desenvolveu às margens do Nilo.","Qual rio foi central para o Egito antigo?",["Nilo","Amazonas","Danúbio"],0,"Resposta correta: Nilo. Sociedades antigas se desenvolveram próximas a rios que favoreciam agricultura e transporte."],["Grécia antiga","As cidades-Estado gregas possuíam governos e costumes próprios.","Atenas é conhecida por sua experiência de democracia direta, restrita a parte da população.","Na Grécia antiga, Atenas ficou associada à:",["Democracia direta","Monarquia absolutista moderna","República presidencialista"],0,"Resposta correta: Democracia direta. As cidades-Estado gregas possuíam governos e costumes próprios."],["Roma antiga","Roma passou por monarquia, república e império ao longo de sua história.","O Senado teve papel político relevante na República romana.","Qual instituição foi importante na República romana?",["Senado","Parlamento europeu","ONU"],0,"Resposta correta: Senado. Roma passou por monarquia, república e império ao longo de sua história."],["Legados da Antiguidade","Povos antigos influenciaram direito, arquitetura, filosofia e formas de organização política.","O direito romano influenciou sistemas jurídicos posteriores.","Qual legado está ligado a Roma?",["Direito romano","Imprensa digital","Máquina a vapor"],0,"Resposta correta: Direito romano. Povos antigos influenciaram direito, arquitetura, filosofia e formas de organização política."]],"História|História do Brasil":[["Povos originários","O território brasileiro era habitado por diversos povos indígenas antes da colonização portuguesa.","Havia grande diversidade de línguas, culturas e formas de organização.","Antes de 1500, o território era:",["Desabitado","Habitado por povos diversos","Uma única cidade"],1,"Resposta correta: Habitado por povos diversos. O território brasileiro era habitado por diversos povos indígenas antes da colonização portuguesa."],["Colonização portuguesa","A colonização envolveu exploração econômica, conflitos e transformações sociais.","A produção açucareira utilizou extensamente trabalho escravizado.","Qual atividade foi importante na economia colonial?",["Produção açucareira","Indústria automobilística","Tecnologia espacial"],0,"Resposta correta: Produção açucareira. A colonização envolveu exploração econômica, conflitos e transformações sociais."],["Independência","A independência política do Brasil foi proclamada em 1822, mas não eliminou a escravidão.","O Brasil tornou-se um império independente.","Em que ano ocorreu a independência do Brasil?",["1822","1889","1930"],0,"Resposta correta: 1822. A independência política do Brasil foi proclamada em 1822, mas não eliminou a escravidão."],["Abolição e República","A escravidão foi legalmente abolida em 1888; a República foi proclamada em 1889.","A Lei Áurea foi assinada em 13 de maio de 1888.","Qual evento ocorreu em 1888?",["Proclamação da República","Abolição legal da escravidão","Independência"],1,"Resposta correta: Abolição legal da escravidão. A escravidão foi legalmente abolida em 1888; a República foi proclamada em 1889."]],"História|História moderna":[["Renascimento","O Renascimento valorizou estudos clássicos e novas abordagens nas artes e ciências.","Artistas exploraram perspectiva e observação da natureza.","Qual área foi marcante no Renascimento?",["Artes e ciências","Informática quântica","Aviação comercial"],0,"Resposta correta: Artes e ciências. O Renascimento valorizou estudos clássicos e novas abordagens nas artes e ciências."],["Reforma protestante","A Reforma do século XVI questionou práticas e a autoridade da Igreja Católica ocidental.","Martinho Lutero divulgou críticas em 1517.","Qual personagem é associado à Reforma?",["Martinho Lutero","Júlio César","Dom Pedro II"],0,"Resposta correta: Martinho Lutero. A Reforma do século XVI questionou práticas e a autoridade da Igreja Católica ocidental."],["Expansão marítima","Expedições europeias ampliaram conexões comerciais e iniciaram processos de conquista e colonização.","Navegações portuguesas chegaram ao oceano Índico por rota marítima ao redor da África.","Qual país participou das grandes navegações?",["Portugal","Canadá","Austrália"],0,"Resposta correta: Portugal. Expedições europeias ampliaram conexões comerciais e iniciaram processos de conquista e colonização."],["Iluminismo","Pensadores iluministas discutiram razão, direitos e limites do poder político.","Montesquieu defendeu a separação de poderes.","Qual ideia é associada ao Iluminismo?",["Separação de poderes","Direito divino incontestável","Fim da investigação científica"],0,"Resposta correta: Separação de poderes. Pensadores iluministas discutiram razão, direitos e limites do poder político."]],"Geografia|Cartografia":[["Elementos do mapa","Título, legenda, orientação e escala ajudam a interpretar mapas.","A legenda explica o significado de símbolos e cores.","O que explica os símbolos do mapa?",["Legenda","Latitude","Altitude"],0,"Resposta correta: Legenda. Título, legenda, orientação e escala ajudam a interpretar mapas."],["Escala cartográfica","A escala relaciona distância no mapa e distância real.","Na escala 1:100.000, 1 cm no mapa representa 1 km no terreno.","Na escala 1:100.000, 2 cm representam:",["200 m","2 km","20 km"],1,"Resposta correta: 2 km. A escala relaciona distância no mapa e distância real."],["Latitude e longitude","Latitude mede posição ao norte ou sul do Equador; longitude, a leste ou oeste de Greenwich.","A linha do Equador corresponde a 0° de latitude.","A latitude é medida em relação:",["Ao Equador","Ao nível do mar","Ao Trópico de Capricórnio apenas"],0,"Resposta correta: Ao Equador. Latitude mede posição ao norte ou sul do Equador; longitude, a leste ou oeste de Greenwich."],["Projeções cartográficas","Projeções representam a superfície curva da Terra em um plano, causando distorções.","A projeção de Mercator preserva ângulos locais, mas amplia áreas em altas latitudes.","Projeções planas sempre apresentam:",["Alguma distorção","Áreas perfeitamente exatas","Ausência de escala"],0,"Resposta correta: Alguma distorção. Projeções representam a superfície curva da Terra em um plano, causando distorções."]],"Geografia|Clima":[["Tempo e clima","Tempo descreve condições atmosféricas momentâneas; clima envolve padrões de longo prazo.","Chuva de hoje é tempo; médias de décadas ajudam a caracterizar clima.","A previsão para amanhã descreve:",["Clima de séculos","Tempo atmosférico","Relevo"],1,"Resposta correta: Tempo atmosférico. Tempo descreve condições atmosféricas momentâneas; clima envolve padrões de longo prazo."],["Elementos climáticos","Temperatura, umidade, pressão e precipitação são elementos do clima.","Pluviômetros medem a precipitação.","Qual instrumento mede chuva?",["Pluviômetro","Sismógrafo","Bússola"],0,"Resposta correta: Pluviômetro. Temperatura, umidade, pressão e precipitação são elementos do clima."],["Fatores do clima","Latitude, altitude, relevo e proximidade do mar influenciam padrões climáticos.","Locais elevados costumam ter temperaturas menores, em condições comparáveis.","Qual fator está relacionado à altura do terreno?",["Altitude","Longitude apenas","Fuso horário"],0,"Resposta correta: Altitude. Latitude, altitude, relevo e proximidade do mar influenciam padrões climáticos."],["Mudanças climáticas","O aumento de gases de efeito estufa por atividades humanas intensifica o aquecimento global.","Queima de combustíveis fósseis emite dióxido de carbono.","Qual atividade emite CO₂?",["Queima de combustíveis fósseis","Evaporação da chuva","Rotação da Terra"],0,"Resposta correta: Queima de combustíveis fósseis. O aumento de gases de efeito estufa por atividades humanas intensifica o aquecimento global."]],"Geografia|Geopolítica":[["Estados e territórios","Estados possuem instituições políticas e exercem soberania sobre territórios, com diferentes formas de organização.","Fronteiras delimitam jurisdições estatais.","O que é uma fronteira política?",["Limite entre jurisdições","Tipo de nuvem","Corrente marítima"],0,"Resposta correta: Limite entre jurisdições. Estados possuem instituições políticas e exercem soberania sobre territórios, com diferentes formas de organização."],["Globalização","Globalização envolve conexões econômicas, culturais e tecnológicas entre regiões.","Cadeias produtivas podem envolver empresas e trabalhadores de vários países.","Uma cadeia produtiva global envolve:",["Apenas uma cidade","Diversos países","Somente agricultura"],1,"Resposta correta: Diversos países. Globalização envolve conexões econômicas, culturais e tecnológicas entre regiões."],["Organizações internacionais","Organizações internacionais promovem cooperação entre países em diferentes temas.","A ONU foi criada em 1945.","Qual organização foi fundada em 1945?",["ONU","Mercosul","União Europeia"],0,"Resposta correta: ONU. Organizações internacionais promovem cooperação entre países em diferentes temas."],["Migrações","Migrações são deslocamentos de pessoas dentro de um país ou entre países, por múltiplas causas.","Pessoas podem migrar por trabalho, estudo, conflitos ou desastres.","Qual exemplo é migração internacional?",["Mudar de país","Trocar de bairro","Viajar pela cidade"],0,"Resposta correta: Mudar de país. Migrações são deslocamentos de pessoas dentro de um país ou entre países, por múltiplas causas."]]};
const expandedLifeSciences:Record<string,[string,string,string,string,[string,string,string],number,string][]> = {"Biologia|Células":[["Membrana plasmática","A membrana delimita a célula e controla a passagem de substâncias.","A difusão transporta partículas a favor do gradiente de concentração.","Qual estrutura controla a entrada e saída de substâncias?",["Membrana plasmática","Ribossomo","Nucléolo"],0,"Resposta: Membrana plasmática. A membrana delimita a célula e controla a passagem de substâncias."],["Citoplasma e organelas","O citoplasma abriga organelas e muitas reações celulares.","Mitocôndrias participam da respiração celular.","Qual organela participa da produção de ATP?",["Lisossomo","Mitocôndria","Centríolo"],1,"Resposta: Mitocôndria. O citoplasma abriga organelas e muitas reações celulares."],["Núcleo e DNA","Em células eucarióticas, o núcleo abriga grande parte do DNA.","O DNA contém informações hereditárias.","O DNA está principalmente em qual região de uma célula eucariótica?",["Parede celular","Núcleo","Membrana"],1,"Resposta: Núcleo. Em células eucarióticas, o núcleo abriga grande parte do DNA."],["Células vegetais e animais","Células vegetais apresentam parede celular e, em geral, cloroplastos; animais não possuem essas estruturas.","Cloroplastos realizam fotossíntese.","Qual estrutura é típica de células vegetais fotossintetizantes?",["Cloroplasto","Centríolo","Hemácia"],0,"Resposta: Cloroplasto. Células vegetais apresentam parede celular e, em geral, cloroplastos; animais não possuem essas estruturas."]],"Biologia|Genética":[["Genes e cromossomos","Genes são segmentos de DNA; cromossomos organizam o material genético.","Seres humanos normalmente têm 46 cromossomos em células somáticas.","Qual molécula compõe os genes?",["DNA","Glicose","Amido"],0,"Resposta: DNA. Genes são segmentos de DNA; cromossomos organizam o material genético."],["Alelos e genótipos","Alelos são versões de um gene; o genótipo representa a combinação de alelos.","Aa é um genótipo heterozigoto.","Qual genótipo é heterozigoto?",["AA","aa","Aa"],2,"Resposta: Aa. Alelos são versões de um gene; o genótipo representa a combinação de alelos."],["Dominância e recessividade","Em dominância completa, um alelo dominante pode determinar o fenótipo em heterozigose.","No exemplo de dominância completa, Aa expressa a característica dominante.","Em dominância completa, Aa expressa:",["Fenótipo dominante","Sempre intermediário","Nenhum fenótipo"],0,"Resposta: Fenótipo dominante. Em dominância completa, um alelo dominante pode determinar o fenótipo em heterozigose."],["Cruzamento monohíbrido","Um quadro de Punnett ajuda a visualizar combinações possíveis de alelos dos gametas.","No cruzamento Aa × Aa, os genótipos possíveis são AA, Aa e aa.","Qual chance de aa em Aa × Aa?",["25%","50%","75%"],0,"Resposta: 25%. Um quadro de Punnett ajuda a visualizar combinações possíveis de alelos dos gametas."]],"Biologia|Ecologia":[["Indivíduo, população e comunidade","População reúne indivíduos da mesma espécie; comunidade reúne populações de espécies diferentes.","Todos os sapos de uma lagoa formam uma população.","Organismos da mesma espécie em uma área formam:",["Comunidade","População","Bioma"],1,"Resposta: População. População reúne indivíduos da mesma espécie; comunidade reúne populações de espécies diferentes."],["Cadeias alimentares","Produtores capturam energia; consumidores obtêm energia alimentando-se de outros organismos.","Capim → gafanhoto → sapo é uma cadeia alimentar.","Qual organismo é produtor nessa cadeia?",["Sapo","Gafanhoto","Capim"],2,"Resposta: Capim. Produtores capturam energia; consumidores obtêm energia alimentando-se de outros organismos."],["Fluxo de energia","A energia flui pelos níveis tróficos, com perdas em forma de calor.","Predadores recebem apenas parte da energia disponível nas presas.","Ao longo dos níveis tróficos, a energia disponível geralmente:",["Diminui","Aumenta sem limite","Fica idêntica"],0,"Resposta: Diminui. A energia flui pelos níveis tróficos, com perdas em forma de calor."],["Ciclos biogeoquímicos","Água, carbono e nitrogênio circulam entre organismos e ambiente.","Evaporação e precipitação participam do ciclo da água.","Qual processo devolve água da atmosfera à superfície?",["Fotossíntese","Precipitação","Respiração"],1,"Resposta: Precipitação. Água, carbono e nitrogênio circulam entre organismos e ambiente."]],"Anatomia|Sistema ósseo":[["Funções do esqueleto","O esqueleto sustenta o corpo, protege órgãos e participa do movimento.","O crânio protege o encéfalo.","Qual estrutura protege o encéfalo?",["Crânio","Fêmur","Rádio"],0,"Resposta: Crânio. O esqueleto sustenta o corpo, protege órgãos e participa do movimento."],["Tipos de ossos","Ossos podem ser longos, curtos, planos ou irregulares conforme sua forma.","O fêmur é classificado como osso longo.","O fêmur é um osso:",["Plano","Longo","Curto"],1,"Resposta: Longo. Ossos podem ser longos, curtos, planos ou irregulares conforme sua forma."],["Articulações","Articulações unem ossos e apresentam diferentes graus de mobilidade.","O joelho permite principalmente flexão e extensão.","Qual estrutura conecta ossos entre si?",["Ligamento","Tendão","Epiderme"],0,"Resposta: Ligamento. Articulações unem ossos e apresentam diferentes graus de mobilidade."],["Medula óssea","A medula óssea vermelha participa da produção de células sanguíneas.","Hemácias são produzidas por processos na medula óssea.","Onde ocorre grande parte da formação de células sanguíneas?",["Medula óssea vermelha","Cartilagem articular","Esmalte dentário"],0,"Resposta: Medula óssea vermelha. A medula óssea vermelha participa da produção de células sanguíneas."]],"Anatomia|Sistema muscular":[["Tipos de tecido muscular","Existem músculos esquelético, cardíaco e liso, com funções e controles diferentes.","O coração possui tecido muscular cardíaco.","Qual tecido compõe a maior parte da parede do coração?",["Liso","Cardíaco","Esquelético"],1,"Resposta: Cardíaco. Existem músculos esquelético, cardíaco e liso, com funções e controles diferentes."],["Contração muscular","A contração muscular depende da interação entre actina e miosina e do uso de ATP.","A contração de fibras musculares movimenta segmentos do corpo.","Quais proteínas participam diretamente da contração?",["Actina e miosina","Hemoglobina e queratina","Insulina e glucagon"],0,"Resposta: Actina e miosina. A contração muscular depende da interação entre actina e miosina e do uso de ATP."],["Tendões e movimento","Tendões conectam músculos aos ossos, transmitindo forças.","O tendão de Aquiles conecta músculos da panturrilha ao calcâneo.","O tendão conecta:",["Osso a osso","Músculo a osso","Nervo a nervo"],1,"Resposta: Músculo a osso. Tendões conectam músculos aos ossos, transmitindo forças."],["Músculos antagonistas","Músculos antagonistas podem produzir movimentos opostos em uma articulação.","Bíceps e tríceps atuam de modo antagonista no cotovelo.","Qual músculo estende o cotovelo?",["Bíceps braquial","Tríceps braquial","Masseter"],1,"Resposta: Tríceps braquial. Músculos antagonistas podem produzir movimentos opostos em uma articulação."]],"Anatomia|Sistema nervoso":[["Neurônios","Neurônios recebem, processam e transmitem sinais por impulsos elétricos e comunicação química.","Dendritos geralmente recebem sinais de outras células.","Qual estrutura geralmente recebe sinais em um neurônio?",["Dendrito","Hemácia","Tendão"],0,"Resposta: Dendrito. Neurônios recebem, processam e transmitem sinais por impulsos elétricos e comunicação química."],["Sistema nervoso central","O sistema nervoso central é formado pelo encéfalo e pela medula espinal.","A medula espinal participa de reflexos.","Qual estrutura integra o sistema nervoso central?",["Nervo periférico","Medula espinal","Músculo"],1,"Resposta: Medula espinal. O sistema nervoso central é formado pelo encéfalo e pela medula espinal."],["Sistema nervoso periférico","Nervos periféricos conectam o sistema nervoso central a estruturas do corpo.","Nervos sensitivos conduzem informações de receptores.","O sistema periférico inclui:",["Nervos","Alvéolos","Artérias apenas"],0,"Resposta: Nervos. Nervos periféricos conectam o sistema nervoso central a estruturas do corpo."],["Arco reflexo","Alguns reflexos envolvem circuitos medulares que permitem respostas rápidas.","Retirar a mão de algo muito quente pode envolver reflexo de retirada.","Qual estrutura pode integrar o reflexo de retirada?",["Medula espinal","Fígado","Pâncreas"],0,"Resposta: Medula espinal. Alguns reflexos envolvem circuitos medulares que permitem respostas rápidas."]],"Anatomia|Sistema circulatório":[["Coração e câmaras","O coração humano possui dois átrios e dois ventrículos.","O ventrículo esquerdo impulsiona sangue para a circulação sistêmica.","Quantos ventrículos tem o coração humano?",["Um","Dois","Quatro"],1,"Resposta: Dois. O coração humano possui dois átrios e dois ventrículos."],["Artérias e veias","Artérias conduzem sangue para fora do coração; veias conduzem sangue de volta.","A aorta sai do ventrículo esquerdo.","Qual vaso leva sangue para fora do coração?",["Artéria","Veia","Capilar linfático"],0,"Resposta: Artéria. Artérias conduzem sangue para fora do coração; veias conduzem sangue de volta."],["Capilares e trocas","Capilares possuem paredes finas que favorecem trocas entre sangue e tecidos.","Oxigênio passa do sangue capilar para células dos tecidos.","Onde ocorrem muitas trocas de gases e nutrientes?",["Capilares","Válvulas cardíacas","Tendões"],0,"Resposta: Capilares. Capilares possuem paredes finas que favorecem trocas entre sangue e tecidos."],["Circulação pulmonar e sistêmica","A circulação pulmonar leva sangue aos pulmões; a sistêmica distribui sangue aos tecidos.","O ventrículo direito bombeia sangue para a circulação pulmonar.","Qual circulação passa pelos pulmões?",["Sistêmica","Pulmonar","Coronária apenas"],1,"Resposta: Pulmonar. A circulação pulmonar leva sangue aos pulmões; a sistêmica distribui sangue aos tecidos."]]};
const expandedSciences:Record<string,[string,string,string,string,[string,string,string],number,string][]> = {"Física|Mecânica":[["Referencial e movimento","Um corpo está em movimento quando sua posição muda em relação a um referencial.","Uma pessoa sentada no ônibus está em repouso em relação ao banco.","Movimento depende de quê?",["Referencial","Cor","Temperatura"],0,"Resposta: Referencial. Um corpo está em movimento quando sua posição muda em relação a um referencial."],["Velocidade média","Velocidade média é deslocamento escalar percorrido dividido pelo tempo, quando se considera distância total e duração total.","150 km em 3 horas correspondem a 50 km/h.","120 km em 2 h equivalem a:",["60 km/h","240 km/h","30 km/h"],0,"Resposta: 60 km/h. Velocidade média é deslocamento escalar percorrido dividido pelo tempo, quando se considera distância total e duração total."],["Aceleração","Aceleração média mede a variação da velocidade por intervalo de tempo.","De 0 a 20 m/s em 5 s: aceleração média de 4 m/s².","De 0 a 12 m/s em 3 s:",["3 m/s²","4 m/s²","12 m/s²"],1,"Resposta: 4 m/s². Aceleração média mede a variação da velocidade por intervalo de tempo."],["Leis de Newton","A força resultante altera o movimento conforme F = m × a.","Uma massa de 2 kg sob força resultante de 10 N acelera 5 m/s².","Massa 3 kg e aceleração 2 m/s²: força resultante?",["5 N","6 N","9 N"],1,"Resposta: 6 N. A força resultante altera o movimento conforme F = m × a."]],"Física|Energia":[["Trabalho mecânico","Uma força realiza trabalho quando provoca deslocamento com componente na direção do movimento.","Força paralela de 10 N ao longo de 3 m realiza 30 J.","Força paralela 5 N por 4 m realiza:",["9 J","20 J","1,25 J"],1,"Resposta: 20 J. Uma força realiza trabalho quando provoca deslocamento com componente na direção do movimento."],["Energia cinética","A energia cinética depende da massa e do quadrado da velocidade: Ec = mv²/2.","Corpo de 2 kg a 3 m/s tem 9 J.","Corpo de 2 kg a 4 m/s tem:",["8 J","16 J","32 J"],1,"Resposta: 16 J. A energia cinética depende da massa e do quadrado da velocidade: Ec = mv²/2."],["Energia potencial gravitacional","Próximo à superfície terrestre, Ep = mgh.","Um corpo de 2 kg a 5 m, com g = 10 m/s², possui 100 J.","Massa 1 kg a 3 m, g = 10: Ep?",["30 J","13 J","3 J"],0,"Resposta: 30 J. Próximo à superfície terrestre, Ep = mgh."],["Conservação de energia","Em sistema isolado, a energia total se conserva mesmo quando muda de forma.","Em uma queda sem resistência do ar, energia potencial transforma-se em cinética.","Em queda ideal, a energia potencial:",["Aumenta sempre","Transforma-se em cinética","Desaparece"],1,"Resposta: Transforma-se em cinética. Em sistema isolado, a energia total se conserva mesmo quando muda de forma."]],"Física|Eletricidade":[["Carga e corrente elétrica","Corrente elétrica é a quantidade de carga que atravessa uma seção por unidade de tempo: I = Q/t.","10 C em 2 s correspondem a 5 A.","12 C em 3 s equivalem a:",["4 A","9 A","36 A"],0,"Resposta: 4 A. Corrente elétrica é a quantidade de carga que atravessa uma seção por unidade de tempo: I = Q/t."],["Tensão elétrica","A tensão representa a diferença de potencial elétrico entre dois pontos.","Uma pilha de 1,5 V estabelece uma diferença de potencial entre seus terminais.","A unidade de tensão é:",["Ampere","Volt","Ohm"],1,"Resposta: Volt. A tensão representa a diferença de potencial elétrico entre dois pontos."],["Resistência e lei de Ohm","Para condutor ôhmico, V = R × I.","Com 5 Ω e 2 A, a tensão é 10 V.","R = 3 Ω e I = 4 A: V =",["7 V","12 V","1 V"],1,"Resposta: 12 V. Para condutor ôhmico, V = R × I."],["Potência elétrica","Potência elétrica indica energia convertida por tempo e pode ser calculada por P = V × I.","Um aparelho de 12 V e 2 A consome 24 W.","10 V e 3 A correspondem a:",["30 W","13 W","3,3 W"],0,"Resposta: 30 W. Potência elétrica indica energia convertida por tempo e pode ser calculada por P = V × I."]],"Física|Óptica":[["Propagação da luz","Em meio homogêneo e transparente, a luz se propaga em linha reta.","Uma sombra nítida surge porque um objeto opaco bloqueia trajetórias da luz.","A formação de sombras está associada à:",["Propagação retilínea","Evaporação","Dilatação"],0,"Resposta: Propagação retilínea. Em meio homogêneo e transparente, a luz se propaga em linha reta."],["Reflexão","Na reflexão, o ângulo de incidência é igual ao ângulo de reflexão, medidos a partir da normal.","Se o raio incide a 30° da normal, reflete a 30°.","Incidência de 40° implica reflexão de:",["20°","40°","80°"],1,"Resposta: 40°. Na reflexão, o ângulo de incidência é igual ao ângulo de reflexão, medidos a partir da normal."],["Refração","A refração ocorre quando a luz atravessa meios com índices diferentes, mudando sua velocidade e, em geral, direção.","Um lápis imerso parcialmente em água parece deslocado.","O lápis parece torto por:",["Refração","Magnetismo","Combustão"],0,"Resposta: Refração. A refração ocorre quando a luz atravessa meios com índices diferentes, mudando sua velocidade e, em geral, direção."],["Espelhos e lentes","Espelhos refletem luz; lentes refratam luz e podem formar imagens reais ou virtuais.","Uma lente convergente pode concentrar raios paralelos em um foco.","Qual dispositivo funciona principalmente por refração?",["Espelho plano","Lente de aumento","Parede"],1,"Resposta: Lente de aumento. Espelhos refletem luz; lentes refratam luz e podem formar imagens reais ou virtuais."]],"Química|Átomos":[["Prótons, nêutrons e elétrons","O núcleo contém prótons e nêutrons; elétrons ocupam regiões ao redor dele.","Átomo neutro com 8 prótons possui 8 elétrons.","Em átomo neutro, prótons e elétrons são:",["Iguais em número","Sempre zero","Sem relação"],0,"Resposta: Iguais em número. O núcleo contém prótons e nêutrons; elétrons ocupam regiões ao redor dele."],["Número atômico","O número atômico Z corresponde à quantidade de prótons.","Oxigênio com Z = 8 tem oito prótons.","Z = 11 indica:",["11 nêutrons","11 prótons","11 moléculas"],1,"Resposta: 11 prótons. O número atômico Z corresponde à quantidade de prótons."],["Número de massa","O número de massa A é a soma de prótons e nêutrons.","6 prótons e 7 nêutrons resultam em A = 13.","8 prótons e 9 nêutrons: A =",["1","17","72"],1,"Resposta: 17. O número de massa A é a soma de prótons e nêutrons."],["Íons e isótopos","Íons resultam de ganho ou perda de elétrons; isótopos possuem o mesmo Z e diferentes números de nêutrons.","Na⁺ tem um elétron a menos que o átomo neutro de sódio.","Um cátion positivo se forma ao:",["Ganhar elétrons","Perder elétrons","Ganhar prótons"],1,"Resposta: Perder elétrons. Íons resultam de ganho ou perda de elétrons; isótopos possuem o mesmo Z e diferentes números de nêutrons."]],"Química|Tabela periódica":[["Períodos e grupos","Períodos são linhas horizontais e grupos são colunas da tabela periódica.","O sódio pertence ao grupo 1.","Os grupos são organizados em:",["Colunas","Diagonais","Linhas apenas"],0,"Resposta: Colunas. Períodos são linhas horizontais e grupos são colunas da tabela periódica."],["Metais e ametais","Metais geralmente conduzem bem calor e eletricidade; ametais apresentam propriedades variadas.","Cobre é um metal usado em fios elétricos.","Qual elemento é metal?",["Oxigênio","Cobre","Cloro"],1,"Resposta: Cobre. Metais geralmente conduzem bem calor e eletricidade; ametais apresentam propriedades variadas."],["Famílias químicas","Elementos do mesmo grupo frequentemente compartilham características químicas.","Lítio e sódio pertencem aos metais alcalinos.","Sódio pertence ao grupo:",["1","18","17"],0,"Resposta: 1. Elementos do mesmo grupo frequentemente compartilham características químicas."],["Gases nobres","Os gases nobres pertencem ao grupo 18 e apresentam baixa reatividade em muitas condições.","Hélio é um gás nobre.","Qual é gás nobre?",["Neônio","Sódio","Ferro"],0,"Resposta: Neônio. Os gases nobres pertencem ao grupo 18 e apresentam baixa reatividade em muitas condições."]],"Química|Reações":[["Reagentes e produtos","Reagentes aparecem antes da seta; produtos, depois.","2 H₂ + O₂ → 2 H₂O: água é produto.","Na equação, H₂O é:",["Reagente","Produto","Catalisador"],1,"Resposta: Produto. Reagentes aparecem antes da seta; produtos, depois."],["Conservação da massa","Em sistema fechado, a massa total dos reagentes é igual à massa total dos produtos.","10 g + 5 g de reagentes formam 15 g de produtos.","Reagentes totalizam 20 g: produtos totalizam:",["10 g","20 g","40 g"],1,"Resposta: 20 g. Em sistema fechado, a massa total dos reagentes é igual à massa total dos produtos."],["Balanceamento","Balancear é ajustar coeficientes para conservar a quantidade de átomos de cada elemento.","2 H₂ + O₂ → 2 H₂O equilibra hidrogênio e oxigênio.","Qual coeficiente antecede H₂O nessa equação?",["1","2","3"],1,"Resposta: 2. Balancear é ajustar coeficientes para conservar a quantidade de átomos de cada elemento."],["Tipos de reação","Síntese combina substâncias; decomposição divide um composto em substâncias mais simples.","2 H₂ + O₂ → 2 H₂O é síntese.","A reação que forma um composto a partir de reagentes mais simples é:",["Síntese","Decomposição","Filtração"],0,"Resposta: Síntese. Síntese combina substâncias; decomposição divide um composto em substâncias mais simples."]],"Química|Ligações":[["Elétrons de valência","Elétrons da camada de valência participam de muitas ligações químicas.","O sódio tende a perder um elétron em certas reações.","Ligações envolvem principalmente:",["Elétrons de valência","Nêutrons do núcleo","Gravidade"],0,"Resposta: Elétrons de valência. Elétrons da camada de valência participam de muitas ligações químicas."],["Ligação iônica","Ligação iônica envolve atração entre íons de cargas opostas após transferência de elétrons.","No NaCl, há atração entre Na⁺ e Cl⁻.","NaCl apresenta ligação predominantemente:",["Metálica","Iônica","Covalente apolar"],1,"Resposta: Iônica. Ligação iônica envolve atração entre íons de cargas opostas após transferência de elétrons."],["Ligação covalente","Na ligação covalente, átomos compartilham pares de elétrons.","Na água, hidrogênio e oxigênio compartilham elétrons.","Compartilhamento caracteriza ligação:",["Covalente","Gravitacional","Nuclear"],0,"Resposta: Covalente. Na ligação covalente, átomos compartilham pares de elétrons."],["Ligação metálica","Metais apresentam ligação metálica, associada à mobilidade de elétrons e boa condução elétrica.","Fios de cobre conduzem corrente com facilidade.","Qual material tem ligação metálica?",["Cobre sólido","Água pura","Gás oxigênio"],0,"Resposta: Cobre sólido. Metais apresentam ligação metálica, associada à mobilidade de elétrons e boa condução elétrica."]]};
export function getLessons(subject:string,topic:string):Lesson[]{
 const basePortuguese=expandedPortuguese[subject+"|"+topic];
 const basePhysics=subject==="Física"?expandedSciences[subject+"|"+topic]:undefined;
 const baseChemistry=subject==="Química"?expandedSciences[subject+"|"+topic]:undefined;
 const curated=basePortuguese?[...basePortuguese,...(expandedPortugueseAdvanced[subject+"|"+topic]||[])]:basePhysics?[...basePhysics,...(expandedPhysicsAdvanced[subject+"|"+topic]||[])]:baseChemistry?[...baseChemistry,...(expandedChemistryAdvanced[subject+"|"+topic]||[])]:expandedSciences[subject+"|"+topic]||expandedLifeSciences[subject+"|"+topic]||expandedHumanities[subject+"|"+topic]||expandedEnglish[subject+"|"+topic];
 if(curated)return curated.map(([title,explain,example,question,options,correct,feedback])=>({title,explain,example,question,options,correct,feedback}));
 const d=entries[subject+"|"+topic];if(!d)return[];
 return [{title:"Entenda o conceito",explain:d.concept,example:d.example,question:d.question,options:d.options,correct:d.correct,feedback:d.detail},{title:"Veja na prática",explain:d.example+" "+d.concept,example:"Observe a explicação e tente resolver sem olhar a resposta.",question:d.question,options:d.options,correct:d.correct,feedback:d.detail},{title:"Revise e pratique",explain:"Revise o conceito central: "+d.concept,example:d.example,question:d.question,options:d.options,correct:d.correct,feedback:d.detail}];
}
